window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[312]={"id":"312","numero":312,"titre":"Tumeurs du sein","objectifs":[{"id":"312-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des tumeurs du sein","contenu":"<p>Le cancer du sein est le <span class=\"kw-def\">cancer le plus fréquent chez la femme</span> en France et le <span class=\"kw-def\">2ème cancer tous sexes confondus</span>. Il représente la <span class=\"kw-alerte\">1ère cause de mortalité par cancer chez la femme</span>, malgré une <span class=\"kw-def\">mortalité</span> en diminution grâce au <span class=\"kw-clinique\">dépistage</span> et aux <span class=\"kw-ttt\">progrès thérapeutiques</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur (France)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Incidence</span> (2018)</td><td><span class=\"kw-chiffre\">~58 500 nouveaux cas/an</span> — <span class=\"kw-def\">incidence</span> en augmentation</td></tr>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">650 000 à 900 000</span> femmes</td></tr>\n          <tr><td>Risque cumulé vie entière</td><td><span class=\"kw-chiffre\">~1 femme sur 8 à 10</span> développera un cancer du sein</td></tr>\n          <tr><td>Âge médian au diagnostic</td><td><span class=\"kw-chiffre\">63 ans</span> — moitié des cas entre <span class=\"kw-chiffre\">45 et 65 ans</span></td></tr>\n          <tr><td>Âge médian au décès</td><td><span class=\"kw-chiffre\">74 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> (2018)</td><td><span class=\"kw-chiffre\">~12 000 décès/an</span> — en diminution</td></tr>\n          <tr><td>Survie globale à <span class=\"kw-chiffre\">5 ans</span></td><td><span class=\"kw-chiffre\">~90 %</span> (forte hétérogénéité selon sous-type et <span class=\"kw-def\">stade</span>)</td></tr>\n          <tr><td>Sexe</td><td><span class=\"kw-chiffre\">&gt; 99 %</span> des cas chez la femme — existe chez l'homme (rare)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> 1<sup>er</sup> en <span class=\"kw-def\">incidence</span> + <span class=\"kw-alerte\">1<sup>ère</sup> cause de mortalité par cancer chez la femme</span>. Couple incidence ↑ / mortalité ↓ = succès du <span class=\"kw-def\">dépistage organisé</span> (<span class=\"kw-chiffre\">50-74 ans</span>) et des <span class=\"kw-ttt\">thérapies ciblées</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/fibroadenoma-breast","label":"Radiopaedia : Fibroadenoma breast"},{"href":"https://radiopaedia.org/articles/fibrocystic-change-breast","label":"Radiopaedia : Fibrocystic change breast"},{"href":"https://radiopaedia.org/articles/phyllodes-tumour-1","label":"Radiopaedia : Phyllodes tumour 1"},{"href":"https://radiopaedia.org/articles/intraductal-papilloma-of-breast","label":"Radiopaedia : Intraductal papilloma of breast"},{"href":"https://radiopaedia.org/articles/breast-hamartoma","label":"Radiopaedia : Breast hamartoma"},{"href":"https://radiopaedia.org/articles/fat-necrosis-breast-2","label":"Radiopaedia : Fat necrosis breast"},{"href":"https://radiopaedia.org/articles/breast-neoplasms","label":"Radiopaedia : Breast neoplasms"},{"href":"https://radiopaedia.org/articles/breast","label":"Radiopaedia : Breast"},{"href":"https://radiopaedia.org/articles/breast-imaging-reporting-and-data-system-bi-rads","label":"Radiopaedia : Breast imaging reporting and data system bi rads"},{"href":"https://radiopaedia.org/articles/breast-ultrasound-1","label":"Radiopaedia : Breast ultrasound 1"},{"href":"http://radiopaedia.org","label":"radiopaedia.org"}]},{"id":"312-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque des tumeurs du sein","contenu":"<p>Maladie <span class=\"kw-def\">multifactorielle</span> : l'âge, l'exposition hormonale endogène et exogène, les antécédents personnels et familiaux et le mode de vie se combinent. L'identification du niveau de risque guide la <span class=\"kw-clinique\">stratégie de dépistage</span> (organisé, individuel, ou très ciblé pour les <span class=\"kw-alerte\">mutations délétères</span>).</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Âge</td>\n            <td><span class=\"kw-chiffre\">Moitié des cas entre 45 et 65 ans</span> — l'âge est le <span class=\"kw-alerte\">FDR principal</span> de la population générale.</td>\n          </tr>\n          <tr>\n            <td>Exposition hormonale</td>\n            <td>\n              <strong>Imprégnation œstrogénique longue :</strong>\n              <ul>\n                <li>Puberté précoce (<span class=\"kw-chiffre\">&lt; 12 ans</span>)</li>\n                <li>Ménopause tardive (<span class=\"kw-chiffre\">&gt; 55 ans</span>)</li>\n                <li>1<sup>ère</sup> <span class=\"kw-ci\">grossesse</span> tardive (<span class=\"kw-chiffre\">&gt; 30 ans</span>)</li>\n                <li><span class=\"kw-clinique\">Pauciparité, nulliparité</span></li>\n                <li><span class=\"kw-clinique\">Absence d'allaitement</span></li>\n              </ul>\n              <strong>Traitements hormonaux :</strong>\n              <ul>\n                <li><span class=\"kw-ttt\">Contraception œstro-progestative</span> (RR <span class=\"kw-chiffre\">1,04</span> — sur-risque faible)</li>\n                <li><span class=\"kw-ttt\">THM</span> dépend du schéma et de la durée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD personnels</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Carcinome in situ</span> (CCIS ou CLIS)</li>\n                <li><span class=\"kw-clinique\">Hyperplasie atypique</span> (canalaire ou lobulaire)</li>\n                <li><span class=\"kw-clinique\">Mastopathie à risque histologique</span></li>\n                <li><span class=\"kw-alerte\">Radiothérapie thoracique haute dose</span> (Hodgkin avant <span class=\"kw-chiffre\">30 ans</span>)</li>\n                <li><span class=\"kw-clinique\">ATCD personnel de cancer du sein</span> : <span class=\"kw-def\">terrain</span> croisé avec cancers de l'<span class=\"kw-clinique\">endomètre</span> et de l'<span class=\"kw-clinique\">ovaire</span> (mutations BRCA) → <span class=\"kw-alerte\">examen gynécologique systématique</span> à toute <span class=\"kw-def\">consultation de suivi</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD familiaux</td>\n            <td>Tenir compte du degré de parenté, de l'âge de survenue, de la bilatéralité et de la multifocalité. Le <span class=\"kw-def\">score d'Eisinger</span> gradue le risque familial : <span class=\"kw-chiffre\">≥ 3</span> = indication formelle de <span class=\"kw-clinique\">consultation d'oncogénétique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Génétique</span></td>\n            <td><span class=\"kw-def\">Syndrome sein-ovaire</span> (BRCA1/2,<span class=\"kw-chiffre\"> 5-10 %</span> des cancers du sein) ; autres : <em>TP53</em> (Li-Fraumeni), <em>CDH1</em>, <em>PALB2</em>, <em>CHEK2</em>, <em>ATM</em>, <em>PTEN</em> (Cowden), <em>STK11</em> (Peutz-Jeghers).</td>\n          </tr>\n          <tr>\n            <td>Mode de vie</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Alcool</span>, <span class=\"kw-clinique\">tabac</span></li>\n                <li><span class=\"kw-clinique\">Surpoids / obésité</span> (surtout post-ménopause)</li>\n                <li><span class=\"kw-clinique\">Sédentarité</span></li>\n                <li>Haut niveau socio-économique (biais de <span class=\"kw-def\">dépistage</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le sur-risque attribué à la contraception œstro-progestative est <span class=\"kw-alerte\">faible</span> (RR 1,04) et ne contre-indique pas la prescription chez une femme sans autre FDR. À l'inverse, une <span class=\"kw-alerte\">irradiation thoracique pour maladie de Hodgkin avant 30 ans</span> impose un <span class=\"kw-def\">dépistage</span> individuel renforcé (mammo + <span class=\"kw-imagerie\">IRM</span> annuelles dès <span class=\"kw-chiffre\">30 ans</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":3},{"id":"312-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les prédispositions génétiques du cancer du sein","contenu":"<p>Les prédispositions héréditaires expliquent <span class=\"kw-chiffre\">5-10 %</span> des cancers du sein et <span class=\"kw-chiffre\">20 %</span> des cancers du sein familiaux. La mutation la plus fréquente porte sur les gènes <span class=\"kw-def\">BRCA1</span> (chromosome 17) et <span class=\"kw-def\">BRCA2</span> (chromosome 13), <span class=\"kw-def\">gènes suppresseurs de tumeurs</span> codant pour des protéines de la <span class=\"kw-def\">réparation de l'ADN par recombinaison homologue</span>. Transmission <span class=\"kw-def\">autosomique dominante</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>BRCA1 / BRCA2</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Mode de transmission</td><td>Autosomique dominante</td></tr>\n          <tr><td>Mécanisme</td><td>Hétérozygotie constitutionnelle + 2<sup>e</sup> mutation somatique sur le brin sain → déficit de la réparation des cassures double-brin → phénotype <span class=\"kw-def\">HRD</span> (<em>Homologous Recombination Deficient</em>)</td></tr>\n          <tr><td>Risque cumulé cancer du sein</td><td><span class=\"kw-chiffre\">60-80 %</span> (âge précoce, multifocal, bilatéral fréquents)</td></tr>\n          <tr><td>Risque cumulé cancer de l'ovaire</td><td><span class=\"kw-chiffre\">~60 %</span> (BRCA1) ; <span class=\"kw-chiffre\">~30 %</span> (BRCA2)</td></tr>\n          <tr><td>Autres cancers (BRCA2)</td><td><span class=\"kw-clinique\">Mélanome</span>, pancréas, prostate, sein chez l'homme</td></tr>\n        </tbody>\n      </table>\n      <h4>Indications d'oncogénétique (cas-index) — ATCD personnels</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Pourquoi suspect</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Cancer du sein <span class=\"kw-chiffre\">≤ 40 ans</span></td><td>Survenue jeune = forte présomption <span class=\"kw-etio\">héréditaire</span></td></tr>\n          <tr><td>Sein + <span class=\"kw-clinique\">ovaire</span> chez la même patiente</td><td>Syndrome <span class=\"kw-def\">sein-ovaire</span> (BRCA1/2)</td></tr>\n          <tr><td>Cancer du sein <span class=\"kw-clinique\">multifocal</span> ou <span class=\"kw-clinique\">bilatéral</span></td><td>Phénotype BRCA-like</td></tr>\n          <tr><td>Cancer du sein chez l'<span class=\"kw-clinique\">homme</span></td><td>Évoque BRCA2</td></tr>\n          <tr><td>Cancer du sein de type <span class=\"kw-clinique\">médullaire</span></td><td>Forme histologique évocatrice de BRCA1</td></tr>\n          <tr><td><span class=\"kw-clinique\">Triple négatif</span> avant <span class=\"kw-chiffre\">60 ans</span></td><td>Sous-type fortement associé à BRCA1</td></tr>\n        </tbody>\n      </table>\n      <p><strong>ATCD familiaux :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">≥ 3</span> cancers du sein chez apparentées au 1<sup>er</sup> ou 2<sup>e</sup> degré</li>\n        <li><span class=\"kw-chiffre\">≥ 2</span> cancers du sein chez apparentées de <span class=\"kw-chiffre\">&lt; 70 ans</span>, dont <span class=\"kw-chiffre\">≥ 1</span> à <span class=\"kw-chiffre\">&lt; 50 ans</span></li>\n        <li><span class=\"kw-chiffre\">≥ 1</span> cancer du sein + 1 cancer de l'ovaire au 1<sup>er</sup> degré</li>\n      </ul>\n      <h4>Mesures préventives en cas de mutation</h4>\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Âge</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Examen clinique des seins</span></td><td>Dès <span class=\"kw-chiffre\">20 ans</span></td><td>Bisannuel</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IRM mammaire</span> + <span class=\"kw-imagerie\">mammographie</span> (<span class=\"kw-def\">incidence</span> oblique unique) ± écho</td><td><span class=\"kw-chiffre\">30 - 65 ans</span></td><td>Annuelle</td></tr>\n          <tr><td><span class=\"kw-ttt\">Mastectomie bilatérale prophylactique</span></td><td>Envisagée dès <span class=\"kw-chiffre\">30 ans</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span> gynécologique ± écho pelvienne</td><td>Dès <span class=\"kw-chiffre\">30-35 ans</span></td><td>Annuelle</td></tr>\n          <tr><td><span class=\"kw-ttt\">Annexectomie bilatérale prophylactique</span></td><td>BRCA1 : <span class=\"kw-chiffre\">40-41 ans</span> ; BRCA2 : <span class=\"kw-chiffre\">45-47 ans</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <h4>Intérêt thérapeutique : anti-PARP</h4>\n      <p>Les cancers BRCA-mutés sont <span class=\"kw-def\">plus chimiosensibles</span> que les cancers sporadiques. La prescription des <span class=\"kw-ttt\">inhibiteurs de PARP</span> (anti-PARP) est conditionnée à la présence d'une mutation BRCA (germinale ou somatique) dans les cancers du <strong>sein</strong>, de la <strong>prostate</strong>, de l'<strong>ovaire</strong> et du <strong>pancréas</strong>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-def\">score d'Eisinger</span> (seuil <span class=\"kw-chiffre\">≥ 3</span>) déclenche la <span class=\"kw-clinique\">consultation d'oncogénétique</span>. Le diagnostic d'une mutation conditionne à la fois la <span class=\"kw-clinique\">surveillance individualisée</span>, la <span class=\"kw-clinique\">chirurgie prophylactique</span> et la <span class=\"kw-clinique\">prescription d'anti-PARP</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur ovaire · 300 — Tumeur col-corps utérin</em></p>","frequence":3},{"id":"312-4","rang":"A","rubrique":"Physiopathologie","titre":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","contenu":"<p>Le cancer du sein naît des cellules de l'<span class=\"kw-def\">appareil sécrétoire</span> du sein (lobules et canaux galactophores). La <span class=\"kw-def\">carcinogenèse</span> suit un processus multi-étapes (<span class=\"kw-def\">initiation, promotion, progression</span>) sous l'influence des <span class=\"kw-def\">œstrogènes</span> (<span class=\"kw-chiffre\">60-70 %</span> des cas — cancer hormono-dépendant).</p>\n      <figure class=\"obj-figure\">\n        <svg viewBox=\"0 0 760 360\" role=\"img\" aria-labelledby=\"t312o3 d312o3\" preserveAspectRatio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:700px;height:auto;margin:0 auto\">\n          <title id=\"t312o3\">Histoire naturelle du cancer du sein</title>\n          <desc id=\"d312o3\">La cellule normale évolue en <span class=\"kw-clinique\">carcinome</span> in situ (membrane basale intacte, sans métastase) puis, après franchissement de la membrane basale, en carcinome invasif qui dissémine par voie lymphatique et hématogène.</desc>\n          <defs>\n            <marker id=\"a312o3\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--ink-muted)\"/></marker>\n            <marker id=\"a312o3r\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--spe-infectio)\"/></marker>\n          </defs>\n          <rect x=\"20\" y=\"40\" width=\"150\" height=\"80\" rx=\"10\" fill=\"var(--ink-muted)\" opacity=\"0.12\"/>\n          <rect x=\"20\" y=\"40\" width=\"150\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--ink-muted)\"/>\n          <text x=\"95\" y=\"74\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Cellule normale</text>\n          <text x=\"95\" y=\"94\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"11\">canal / lobule</text>\n          <line x1=\"170\" y1=\"80\" x2=\"242\" y2=\"80\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o3)\"/>\n          <text x=\"206\" y=\"70\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10\">carcinogenèse</text>\n          <rect x=\"250\" y=\"40\" width=\"190\" height=\"80\" rx=\"10\" fill=\"var(--spe-pneumo)\" opacity=\"0.16\"/>\n          <rect x=\"250\" y=\"40\" width=\"190\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-pneumo)\"/>\n          <text x=\"345\" y=\"66\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Carcinome in situ</text>\n          <text x=\"345\" y=\"85\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">membrane basale intacte</text>\n          <text x=\"345\" y=\"104\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"11\" font-weight=\"700\">métastase NULLE</text>\n          <line x1=\"498\" y1=\"34\" x2=\"498\" y2=\"126\" stroke=\"var(--spe-infectio)\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n          <line x1=\"440\" y1=\"80\" x2=\"560\" y2=\"80\" stroke=\"var(--spe-infectio)\" stroke-width=\"2.5\" marker-end=\"url(#a312o3r)\"/>\n          <text x=\"500\" y=\"145\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10\" font-weight=\"600\">franchit la membrane basale</text>\n          <rect x=\"570\" y=\"40\" width=\"170\" height=\"80\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.16\"/>\n          <rect x=\"570\" y=\"40\" width=\"170\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"/>\n          <text x=\"655\" y=\"74\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Carcinome invasif</text>\n          <text x=\"655\" y=\"94\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"11\" font-weight=\"700\">métastase +</text>\n          <line x1=\"655\" y1=\"120\" x2=\"410\" y2=\"172\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o3)\"/>\n          <text x=\"398\" y=\"165\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"11\" font-weight=\"600\">Dissémination</text>\n          <line x1=\"400\" y1=\"174\" x2=\"235\" y2=\"196\" stroke=\"var(--ink-muted)\" stroke-width=\"1.5\"/>\n          <line x1=\"400\" y1=\"174\" x2=\"525\" y2=\"196\" stroke=\"var(--ink-muted)\" stroke-width=\"1.5\"/>\n          <rect x=\"110\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"var(--spe-cardio)\" opacity=\"0.13\"/>\n          <rect x=\"110\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-cardio)\"/>\n          <text x=\"235\" y=\"222\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"12.5\" font-weight=\"700\">Voie lymphatique</text>\n          <text x=\"126\" y=\"250\" fill=\"var(--ink)\" font-size=\"11\">• Creux axillaire (relais princ.)</text>\n          <text x=\"126\" y=\"276\" fill=\"var(--ink)\" font-size=\"11\">• Sus- / sous-claviculaires</text>\n          <text x=\"126\" y=\"302\" fill=\"var(--ink)\" font-size=\"11\">• Chaîne mammaire interne</text>\n          <text x=\"126\" y=\"322\" fill=\"var(--ink-muted)\" font-size=\"10\">(non accessible à l'examen)</text>\n          <rect x=\"400\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.13\"/>\n          <rect x=\"400\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"/>\n          <text x=\"525\" y=\"222\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"12.5\" font-weight=\"700\">Voie hématogène</text>\n          <text x=\"416\" y=\"250\" fill=\"var(--ink)\" font-size=\"11\">• Os</text>\n          <text x=\"416\" y=\"276\" fill=\"var(--ink)\" font-size=\"11\">• Poumon</text>\n          <text x=\"416\" y=\"302\" fill=\"var(--ink)\" font-size=\"11\">• Foie</text>\n          <text x=\"416\" y=\"322\" fill=\"var(--ink-muted)\" font-size=\"10\">+ SNC si HER2+ · péritoine si lobulaire</text>\n        </svg>\n        <figcaption>Le carcinome <strong>in situ</strong> ne métastase pas ; tout bascule au <strong>franchissement de la membrane basale</strong>, qui ouvre les voies lymphatique et hématogène.</figcaption>\n      </figure>\n      <h4>Étapes histologiques</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th><span class=\"kw-clinique\">Carcinome</span> in situ</th><th>Carcinome invasif (infiltrant)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Définition</td>\n            <td><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-def\">intra-épithéliale</span> (contenu à l'intérieur du canal ou du lobule) — pas de franchissement de la <span class=\"kw-def\">membrane basale</span></td>\n            <td><span class=\"kw-def\">Franchissement de la membrane basale</span></td>\n          </tr>\n          <tr>\n            <td>Risque métastatique</td>\n            <td><span class=\"kw-clinique\">Nul</span> (pas de dissémination à distance)</td>\n            <td>Présent — <span class=\"kw-def\">lymphatique</span> et <span class=\"kw-def\">hématogène</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Évolution</span></td>\n            <td>Dissémination canalaire dans le sein → mastectomie souvent indiquée ; progression possible en plusieurs années vers un cancer invasif</td>\n            <td>Dissémination locale + ganglionnaire + à distance</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Modes de dissémination du <span class=\"kw-clinique\">carcinome</span> invasif</h4>\n      <table >\n        <thead>\n          <tr><th>Voie</th><th>Sites concernés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Lymphatique</span></td>\n            <td>\n              <ul>\n                <li>Ganglions du <strong>creux axillaire</strong> (relais principal)</li>\n                <li>Ganglions <strong>sus-</strong> et <strong>sous-claviculaires</strong></li>\n                <li>Ganglions de la <strong>chaîne mammaire interne</strong> (non accessibles à l'examen clinique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hématogène</span></td>\n            <td>\n              Sites préférentiels : <span class=\"kw-clinique\">os</span>, <span class=\"kw-clinique\">poumons</span>, <span class=\"kw-clinique\">foie</span>.<br>\n              <span class=\"kw-alerte\">Carcinose péritonéale et pleurale</span> : fréquente dans le <span class=\"kw-clinique\">carcinome</span> <strong>lobulaire infiltrant</strong>.<br>\n              Métastases <span class=\"kw-clinique\">cérébrales (SNC)</span> : fréquence élevée dans le sous-type <strong>HER2+</strong>.<br>\n              Autres : <span class=\"kw-clinique\">peau</span>, <span class=\"kw-clinique\">ovaires</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Particularités évolutives selon sous-type moléculaire</h4>\n      <table >\n        <thead>\n          <tr><th>Sous-type</th><th>Particularité de dissémination / récidive</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Carcinome lobulaire infiltrant</span></td>\n            <td>Tropisme <span class=\"kw-alerte\">péritonéal et pleural</span> (carcinose) ; volontiers multifocal et bilatéral</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">HER2+</span></td>\n            <td>Tropisme <span class=\"kw-alerte\">cérébral (SNC)</span> fréquent</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Triple négatif</span></td>\n            <td>Récidive <span class=\"kw-alerte\">précoce (2-3 premières années)</span> ; mauvais <span class=\"kw-def\">pronostic</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-clinique\">carcinome</span> in situ est <span class=\"kw-clinique\">non métastasant</span> mais peut évoluer vers une forme invasive. Le carcinome <strong>lobulaire</strong> infiltrant a une dissémination volontiers <span class=\"kw-clinique\">péritonéale</span> ; le sous-type <strong>HER2+</strong> a un tropisme <span class=\"kw-clinique\">cérébral</span> ; les cancers <strong>triple négatifs</strong> récidivent plus précocement (2-3 premières années).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 309 — Tumeurs du poumon</em></p>","frequence":0},{"id":"312-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différentes modalités de dépistage","contenu":"<p>L'<span class=\"kw-def\">examen clinique mammaire annuel</span> est recommandé chez toutes les femmes à partir de <span class=\"kw-chiffre\">25 ans</span>. La stratégie paraclinique dépend du niveau de risque : <span class=\"kw-def\">dépistage organisé</span> pour la population générale, <span class=\"kw-def\">dépistage individuel</span> pour les femmes à haut risque, et <span class=\"kw-def\">programme personnalisé</span> pour les très hauts risques (BRCA1/2).</p>\n      <figure class=\"obj-figure\">\n        <svg viewBox=\"0 0 760 305\" role=\"img\" aria-labelledby=\"t312o4 d312o4\" preserveAspectRatio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:660px;height:auto;margin:0 auto\">\n          <title id=\"t312o4\">Stratégie de <span class=\"kw-def\">dépistage</span> selon le niveau de risque</title>\n          <desc id=\"d312o4\">Trois niveaux de risque en escalier : risque moyen (<span class=\"kw-imagerie\">mammographie</span> tous les <span class=\"kw-chiffre\">2 ans</span> de <span class=\"kw-chiffre\">50 à 74 ans</span>), risque élevé (<span class=\"kw-imagerie\">mammographie</span> et <span class=\"kw-imagerie\">échographie</span> annuelles) et très haut risque (<span class=\"kw-imagerie\">IRM</span>, <span class=\"kw-imagerie\">mammographie</span> et <span class=\"kw-imagerie\">échographie</span> annuelles dès <span class=\"kw-chiffre\">30 ans</span>).</desc>\n          <defs>\n            <marker id=\"a312o4\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--ink-muted)\"/></marker>\n          </defs>\n          <rect x=\"40\" y=\"190\" width=\"210\" height=\"80\" rx=\"10\" fill=\"var(--spe-pneumo)\" opacity=\"0.16\"/>\n          <rect x=\"40\" y=\"190\" width=\"210\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-pneumo)\"/>\n          <text x=\"56\" y=\"214\" fill=\"var(--spe-pneumo)\" font-size=\"13\" font-weight=\"700\">Risque moyen</text>\n          <text x=\"56\" y=\"234\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Population générale</text>\n          <text x=\"56\" y=\"254\" fill=\"var(--ink)\" font-size=\"11\">Mammo ± écho · /<span class=\"kw-chiffre\">2 ans</span></text>\n          <text x=\"56\" y=\"268\" fill=\"var(--ink-muted)\" font-size=\"10\"><span class=\"kw-chiffre\">50–74 ans</span></text>\n          <rect x=\"270\" y=\"140\" width=\"210\" height=\"130\" rx=\"10\" fill=\"var(--spe-orl)\" opacity=\"0.16\"/>\n          <rect x=\"270\" y=\"140\" width=\"210\" height=\"130\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-orl)\"/>\n          <text x=\"286\" y=\"164\" fill=\"var(--spe-orl)\" font-size=\"13\" font-weight=\"700\">Risque élevé</text>\n          <text x=\"286\" y=\"186\" fill=\"var(--ink-muted)\" font-size=\"10.5\">ATCD perso/fam., Hodgkin</text>\n          <text x=\"286\" y=\"210\" fill=\"var(--ink)\" font-size=\"11\">Mammo + <span class=\"kw-imagerie\">échographie</span></text>\n          <text x=\"286\" y=\"230\" fill=\"var(--ink-muted)\" font-size=\"10.5\">annuelle, à vie</text>\n          <rect x=\"500\" y=\"90\" width=\"210\" height=\"180\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.16\"/>\n          <rect x=\"500\" y=\"90\" width=\"210\" height=\"180\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"/>\n          <text x=\"516\" y=\"116\" fill=\"var(--spe-infectio)\" font-size=\"13\" font-weight=\"700\">Très haut risque</text>\n          <text x=\"516\" y=\"138\" fill=\"var(--ink-muted)\" font-size=\"10.5\">BRCA1/2, TP53, PALB2…</text>\n          <text x=\"516\" y=\"162\" fill=\"var(--ink)\" font-size=\"11\">Examen clin. dès <span class=\"kw-chiffre\">20 ans</span></text>\n          <text x=\"516\" y=\"184\" fill=\"var(--ink)\" font-size=\"11\"><span class=\"kw-imagerie\">IRM</span> + mammo + écho /an</text>\n          <text x=\"516\" y=\"204\" fill=\"var(--ink-muted)\" font-size=\"10\"><span class=\"kw-chiffre\">30–65 ans</span></text>\n          <line x1=\"40\" y1=\"288\" x2=\"712\" y2=\"288\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o4)\"/>\n          <text x=\"376\" y=\"302\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">risque croissant → <span class=\"kw-def\">surveillance</span> plus précoce, rapprochée et sensible</text>\n        </svg>\n        <figcaption>Plus le risque est élevé, plus la surveillance commence <strong>tôt</strong>, se fait <strong>rapprochée</strong> et gagne en sensibilité avec l'<strong><span class=\"kw-imagerie\">IRM</span></strong>.</figcaption>\n      </figure>\n      <h4>Trois niveaux de risque, trois stratégies</h4>\n      <table >\n        <thead>\n          <tr><th>Niveau de risque</th><th>Définition</th><th><span class=\"kw-def\">Dépistage</span> paraclinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque moyen</strong></td>\n            <td>Toutes les femmes sans FDR particulier</td>\n            <td><strong><span class=\"kw-def\">Dépistage</span> organisé :</strong><br><span class=\"kw-imagerie\">Mammographie</span> bilatérale <span class=\"kw-radio\">2 incidences</span> <br>Tous les <span class=\"kw-chiffre\">2 ans</span> entre <span class=\"kw-chiffre\">50 et 74 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Haut risque (risque élevé)</strong></td>\n            <td>\n              <ul>\n                <li>Forme familiale avérée sans mutation identifiée</li>\n                <li>ATCD d'<span class=\"kw-alerte\">irradiation thoracique haute dose</span> (Hodgkin)</li>\n                <li>ATCD personnel : <span class=\"kw-clinique\">hyperplasie atypique</span>, CLIS, CCIS, cancer du sein</li>\n              </ul>\n            </td>\n            <td><strong><span class=\"kw-def\">Dépistage</span> individuel :</strong><br><span class=\"kw-imagerie\">Mammographie</span> + <span class=\"kw-imagerie\">échographie</span> annuelle à vie</td>\n          </tr>\n          <tr>\n            <td><strong>Très haut risque</strong></td>\n            <td><span class=\"kw-alerte\">Mutation délétère BRCA1/2</span> ou autres prédispositions (TP53, PALB2…)</td>\n            <td><strong>Programme personnalisé :</strong> <span class=\"kw-clinique\">examen clinique bisannuel</span> dès <span class=\"kw-chiffre\">20 ans</span> ; <span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-imagerie\">mammographie</span> + écho annuelles entre <span class=\"kw-chiffre\">30-65 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-def\">Dépistage</span> organisé du cancer du sein</h4>\n      <p>Programme national instauré en <span class=\"kw-chiffre\">2004</span>. Invitation systématique par courrier de toutes les femmes de <span class=\"kw-chiffre\">50-74 ans</span> sans FDR significatif autre que l'âge et <strong>sans signes cliniques</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Tous les <span class=\"kw-chiffre\">2 ans</span></td></tr>\n          <tr><td><strong>Moyens</strong></td><td><span class=\"kw-clinique\">Examen clinique mammaire</span> + <span class=\"kw-imagerie\">mammographie</span> bilatérale avec <span class=\"kw-radio\">2 incidences</span> (<em>oblique externe</em> + <em>cranio-caudale</em>)</td></tr>\n          <tr><td><strong>2<sup>nde</sup> lecture systématique</strong></td><td>Mammographies <span class=\"kw-radio\">ACR 1 ou ACR 2</span> par un radiologue indépendant (lit ≥ <span class=\"kw-chiffre\">1500</span> mammographies supplémentaires/an)</td></tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span class=\"kw-chiffre\">100 %</span> par l'assurance maladie</td></tr>\n          <tr><td><strong>Objectif</strong></td><td><span class=\"kw-ttt\">Réduction</span> de la <span class=\"kw-def\">mortalité</span> par cancer du sein</td></tr>\n          <tr><td><strong>Participation 2017</strong></td><td><span class=\"kw-chiffre\">~50 %</span> (insuffisant)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-def\">dépistage</span> organisé est <span class=\"kw-alerte\">contre-indiqué chez les femmes symptomatiques</span> : devant tout signe clinique (<span class=\"kw-clinique\">nodule</span>, <span class=\"kw-clinique\">écoulement</span>, <span class=\"kw-clinique\">rétraction</span>…), on bascule en <span class=\"kw-def\">démarche diagnostique</span> et non en dépistage. Un dépistage ne se fait jamais sur un sein malade.</div>","frequence":3},{"id":"312-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques des tumeurs du sein","contenu":"<p>L'examen des seins est <strong>bilatéral et comparatif</strong>, en position debout puis couchée, par <span class=\"kw-clinique\">inspection puis palpation</span>. Tout signe clinique nouveau impose une démarche diagnostique (<span class=\"kw-imagerie\">mammographie</span> ± <span class=\"kw-imagerie\">échographie</span> ± <span class=\"kw-clinique\">biopsie</span>). <span class=\"kw-alerte\">L'apparition d'un nodule du sein chez une femme ménopausée doit faire suspecter un cancer du sein jusqu'à preuve du contraire.</span></p>\n      <h4>Signes cliniques par catégorie</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Symptômes</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Douleur mammaire</span> (mastodynie)</li>\n                <li><span class=\"kw-clinique\">Écoulement mamelonnaire suspect :</span> apparition récente, <strong>spontané</strong>, <strong>unilatéral</strong>, <strong>unipore</strong>, couleur <strong>claire</strong>, <strong>jaune séreux</strong>, <strong>rouge sanglant</strong> ou <strong>noir</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications du sein</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Ascension du sein, asymétrie, augmentation de volume</span></li>\n                <li><span class=\"kw-clinique\">Nodule / masse mammaire</span> — cancer jusqu'à preuve du contraire chez la femme ménopausée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications du mamelon</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Déviation</span>, <span class=\"kw-clinique\">invagination</span> ou <span class=\"kw-clinique\">rétraction</span> du mamelon</li>\n                <li>Aspect <span class=\"kw-clinique\">eczématiforme</span> du mamelon → évoque la <span class=\"kw-alerte\">maladie de Paget</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications cutanées</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Rétraction cutanée</span>, <span class=\"kw-clinique\">fossette, méplat</span> (recherche à l'éclairage jour frisant, bras pendants puis relevés)</li>\n                <li><span class=\"kw-clinique\">Squirrhe mammaire</span> (tumeur dure avec épaississement ± bourgeonnement)</li>\n                <li><span class=\"kw-clinique\">Ulcération cutanée</span>, <span class=\"kw-clinique\">nodules de perméation</span></li>\n                <li>Empâtement, <span class=\"kw-clinique\">lésion</span> croûteuse</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Inflammation (T4d)</span></td>\n            <td>\n              Cancer <span class=\"kw-etio\">inflammatoire</span> défini par l'association de :\n              <ul>\n                <li><span class=\"kw-clinique\">Placard</span> <span class=\"kw-clinique\">érythémateux chaud</span> ± douloureux</li>\n                <li><span class=\"kw-clinique\">Œdème</span> cutané avec aspect de <strong>« peau d'orange »</strong></li>\n                <li>Présence de ces signes sur <span class=\"kw-chiffre\">≥ 1/3 du sein</span></li>\n                <li><span class=\"kw-clinique\">Évolution</span> <strong>rapide en quelques semaines</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Adhérence</td>\n            <td>\n              <ul>\n                <li><strong>Pincement de la peau</strong> en regard de la tumeur : mobilité / peau</li>\n                <li><strong><span class=\"kw-def\">Manœuvre de Tillaux</span></strong> (adduction contrariée du bras) : mobilité / muscle grand pectoral</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Adénopathies</span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Axillaires ± sus-claviculaires</span> : augmentées de volume, dures</li>\n                <li>Aires <strong>mammaires internes</strong> : non accessibles à l'examen clinique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Métastases révélatrices</td>\n            <td><span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">douleurs osseuses</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">céphalées</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 208\" role=\"img\" aria-label=\"Schéma de convergence : les quatre critères placard érythémateux chaud, œdème en peau d'orange, signes sur au moins un tiers du sein et évolution rapide en quelques semaines définissent par leur association le cancer du sein inflammatoire de stade T4d.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Cancer du sein <span class=\"kw-etio\">inflammatoire</span> (T4d) — 4 critères associés</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"28\" width=\"224\" height=\"38\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"124\" y=\"51\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span class=\"kw-clinique\">Placard</span> érythémateux chaud</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"72\" width=\"224\" height=\"38\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"124\" y=\"95\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span class=\"kw-clinique\">Œdème</span> « peau d'orange »</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"116\" width=\"224\" height=\"38\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"124\" y=\"139\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\">Signes sur <span class=\"kw-chiffre\">≥ 1</span>/3 du sein</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"160\" width=\"224\" height=\"38\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"124\" y=\"183\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span class=\"kw-clinique\">Évolution</span> rapide (qq semaines)</text>\n          <rect class=\"fb-red\" x=\"320\" y=\"78\" width=\"228\" height=\"72\" rx=\"8\"/>\n          <text class=\"tx-red\" x=\"434\" y=\"110\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Cancer du sein</text>\n          <text class=\"tx-red\" x=\"434\" y=\"128\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">inflammatoire (T4d)</text>\n          <line class=\"ln\" x1=\"236\" y1=\"47\" x2=\"314\" y2=\"92\" stroke-width=\"1.5\"/>\n          <polygon class=\"ah\" points=\"320,92 312,88 312,96\"/>\n          <line class=\"ln\" x1=\"236\" y1=\"91\" x2=\"314\" y2=\"106\" stroke-width=\"1.5\"/>\n          <polygon class=\"ah\" points=\"320,106 312,102 312,110\"/>\n          <line class=\"ln\" x1=\"236\" y1=\"135\" x2=\"314\" y2=\"120\" stroke-width=\"1.5\"/>\n          <polygon class=\"ah\" points=\"320,120 312,116 312,124\"/>\n          <line class=\"ln\" x1=\"236\" y1=\"179\" x2=\"314\" y2=\"134\" stroke-width=\"1.5\"/>\n          <polygon class=\"ah\" points=\"320,134 312,130 312,138\"/>\n        </svg>\n        <figcaption>Le cancer du sein inflammatoire (T4d) se définit par l'<strong>association</strong> des 4 critères — mastectomie + curage + <span class=\"kw-ttt\">chimiothérapie</span> néoadjuvante, quel que soit le sous-type.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> L'association <span class=\"kw-alerte\">érythème chaud + œdème en peau d'orange + évolution rapide en quelques semaines + atteinte de ≥ 1/3 du sein</span> définit le <span class=\"kw-def\">cancer du sein inflammatoire (T4d)</span>. <span class=\"kw-ttt\">Mastectomie totale</span> + <span class=\"kw-clinique\">curage axillaire</span> + <span class=\"kw-ttt\">chimiothérapie néoadjuvante</span> systématique, quel que soit le sous-type moléculaire.</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'<span class=\"kw-clinique\">eczéma</span> du mamelon n'est <span class=\"kw-alerte\">jamais banal</span> : un aspect eczématiforme persistant et unilatéral de la <span class=\"kw-clinique\">plaque</span> aréolo-mamelonnaire évoque une <span class=\"kw-def\">maladie de Paget</span> du sein → <span class=\"kw-clinique\">punch-biopsie cutanée</span> systématique.</div>","frequence":4},{"id":"312-7","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies de lésions/anomalies cutanées sein","contenu":"<p>Cet objectif est un objectif de <span class=\"kw-def\">reconnaissance visuelle</span> : à l'EDN, les <span class=\"kw-clinique\">vignettes</span> peuvent présenter une photographie clinique du sein et demander d'identifier le <span class=\"kw-clinique\">signe cutané</span> et le diagnostic évoqué. La sémiologie textuelle à connaître recouvre les principales présentations visibles à l'<span class=\"kw-clinique\">inspection</span>.</p>\n      <h4>Cinq signes cutanés à reconnaître</h4>\n      <table >\n        <thead>\n          <tr><th>Signe</th><th>Description</th><th>Diagnostic évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Maladie de Paget</span> du mamelon</td>\n            <td>Aspect <strong>eczématiforme</strong> du mamelon et de l'aréole : <span class=\"kw-clinique\">érythème, érosion, croûtes, prurit</span>, unilatéral et persistant malgré les soins locaux</td>\n            <td><span class=\"kw-alerte\">Carcinome canalaire associé</span> (in situ ou invasif) → <span class=\"kw-clinique\">punch-biopsie cutanée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Peau d'orange</span></td>\n            <td><span class=\"kw-clinique\">Œdème cutané dermique</span> donnant un aspect d'orifices pilo-sébacés saillants — souvent associé à <span class=\"kw-clinique\">érythème et chaleur</span></td>\n            <td><span class=\"kw-alerte\">Cancer du sein inflammatoire (T4d)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Rétraction cutanée</span></td>\n            <td><span class=\"kw-clinique\">Fossette ou méplat localisé</span> en regard d'une tumeur sous-jacente — visible à l'inspection bras relevés, parfois uniquement à l'éclairage frisant</td>\n            <td><span class=\"kw-clinique\">Cancer infiltrant</span> avec <span class=\"kw-clinique\">adhérence cutanée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Ulcération cutanée</span></td>\n            <td><span class=\"kw-clinique\">Perte de substance bourgeonnante ou nécrotique</span>, parfois associée à des <span class=\"kw-clinique\">nodules de perméation</span></td>\n            <td>Cancer évolué (souvent <span class=\"kw-radio\">T4b</span>) découvert tardivement</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Écoulement sanglant</span></td>\n            <td><span class=\"kw-clinique\">Goutte de sang spontanée, unilatérale, unipore</span> — visible à l'inspection ou provoquée par pression douce</td>\n            <td><span class=\"kw-clinique\">Cancer canalaire</span> ou <span class=\"kw-etio\">papillome intra-canalaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> Cet objectif attend des photographies cliniques (Paget, peau d'orange, rétraction, <span class=\"kw-clinique\">ulcération</span>, écoulement sanglant). Aucune image n'a été fournie au build initial — Kevin les ajoutera en B-FIX ultérieur. La sémiologie textuelle ci-dessus suffit pour la révision écrite ; les images seront ajoutées via <code>assets/images/312/</code> avec attribut <code>alt</code> descriptif.</div>","frequence":0},{"id":"312-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications de la mammographie","contenu":"<p>La <span class=\"kw-def\">mammographie</span> est l'examen de <strong>1<sup>ère</sup> intention</strong> devant toute anomalie mammaire ou dans le cadre du <span class=\"kw-def\">dépistage</span>. Elle est <span class=\"kw-ci\">contre-indiquée</span> chez la femme très jeune (<span class=\"kw-chiffre\">&lt; 30 ans</span>) et chez la <span class=\"kw-clinique\">femme enceinte</span> (seins denses non lisibles) — on lui substitue l'<span class=\"kw-imagerie\">échographie</span>.</p>\n      <h4>Modalités techniques</h4>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Réalisation</strong></td><td>Radiologue agréé formé (<span class=\"kw-chiffre\">≥ 500 mammographies/an</span>)</td></tr>\n          <tr><td><strong>2 incidences systématiques</strong></td><td>Oblique externe + cranio-caudale</td></tr>\n          <tr><td><strong>Période optimale</strong> (femme non ménopausée)</td><td><span class=\"kw-clinique\">1<sup>ère</sup> partie de cycle</span> (seins moins denses et moins douloureux)</td></tr>\n          <tr><td><strong>Comparaison</strong></td><td>Bilatérale + avec les clichés antérieurs si disponibles</td></tr>\n          <tr><td><strong>Compléments possibles</strong></td><td><span class=\"kw-imagerie\">Tomosynthèse 3D</span>, clichés profil ou agrandis, compression localisée</td></tr>\n        </tbody>\n      </table>\n      <h4>Indications</h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> organisé</strong></td>\n            <td>Femmes <span class=\"kw-chiffre\">50-74 ans</span> tous les <span class=\"kw-chiffre\">2 ans</span>, sans signes cliniques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> individuel</strong></td>\n            <td>Femmes à haut risque (ATCD personnels, familiaux, <span class=\"kw-clinique\">irradiation</span> thoracique, <span class=\"kw-clinique\">lésion</span> à risque) : <span class=\"kw-imagerie\">mammographie</span> annuelle</td>\n          </tr>\n          <tr>\n            <td><strong>Démarche diagnostique</strong></td>\n            <td>Toute anomalie clinique mammaire (<span class=\"kw-clinique\">nodule</span>, <span class=\"kw-clinique\">écoulement suspect</span>, <span class=\"kw-clinique\">rétraction</span>, modification cutanée)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Bilan préthérapeutique</span></strong></td>\n            <td>Mammographie bilatérale systématique avant traitement d'un cancer du sein</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span> post-traitement</strong></td>\n            <td>1 fois/an à vie ou jusqu'à la 10<sup>e</sup> année (sauf si mastectomie totale)</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Sémiologie : <span class=\"kw-clinique\">lésion</span> suspecte <span class=\"kw-bio\">vs</span> bénigne</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th><span class=\"kw-clinique\">Nodule</span> malin</th><th>Nodule bénin</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Limites / contours</td><td><span class=\"kw-radio\">Mal limité, irrégulier, spiculé</span>, rétractile</td><td>Limites nettes</td></tr>\n          <tr><td>Densité</td><td>Hétérogène, centre dense, halo clair œdémateux</td><td>Homogène</td></tr>\n          <tr><td>Architecture</td><td><span class=\"kw-radio\">Rupture architecturale</span></td><td>Respectée</td></tr>\n          <tr><td>Calcifications</td><td><span class=\"kw-radio\">Microcalcifications</span> vermiculaires, arborescentes, irrégulières, groupées, topographie galactophorique</td><td><span class=\"kw-radio\">Macrocalcifications</span></td></tr>\n          <tr><td>Échogénicité</td><td><span class=\"kw-radio\">Hypoéchogène</span></td><td><span class=\"kw-radio\">Anéchogène</span> (kyste)</td></tr>\n          <tr><td>Grand axe</td><td><span class=\"kw-radio\">Perpendiculaire à la peau</span> (= vertical)</td><td><span class=\"kw-radio\">Parallèle à la peau</span> (dans le sens des canaux galactophoriques)</td></tr>\n          <tr><td>Postérieur (écho)</td><td><span class=\"kw-radio\">Cône d'ombre postérieur</span></td><td><span class=\"kw-radio\">Renforcement postérieur</span></td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-def\">Classification</span> BI-RADS (<span class=\"kw-alerte\">ACR</span>)</h4>\n      <table >\n        <thead>\n          <tr><th>Classe ACR</th><th>Signification</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-radio\">ACR 0</span></strong></td><td>Examen incomplet</td><td>Complément à demander</td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 1</span></strong></td><td>Examen normal</td><td>Aucune action</td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 2</span></strong></td><td>Anomalie bénigne</td><td>Pas de <span class=\"kw-def\">surveillance</span> particulière</td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 3</span></strong></td><td>Anomalie probablement bénigne</td><td><span class=\"kw-imagerie\">Surveillance à 6 mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 4</span></strong></td><td>Anomalie suspecte</td><td><span class=\"kw-clinique\">Biopsie indispensable</span></td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 5</span></strong></td><td>Anomalie évocatrice de malignité</td><td><span class=\"kw-clinique\">Biopsie indispensable</span></td></tr>\n          <tr><td><strong><span class=\"kw-radio\">ACR 6</span></strong></td><td>Cancer prouvé histologiquement</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg viewBox=\"0 0 760 150\" role=\"img\" aria-labelledby=\"t312o7 d312o7\" preserveAspectRatio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:720px;height:auto;margin:0 auto\">\n          <title id=\"t312o7\">Échelle BI-RADS (<span class=\"kw-alerte\">ACR</span>) et conduite à tenir</title>\n          <desc id=\"d312o7\"><span class=\"kw-def\">Classification</span> ACR de 0 à 6 par risque croissant de malignité ; le seuil décisif se situe entre ACR 3 (<span class=\"kw-def\">surveillance</span>) et ACR 4 (<span class=\"kw-ttt\">biopsie</span> obligatoire).</desc>\n          <text x=\"215\" y=\"28\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10\">ACR 0–3 : pas de biopsie</text>\n          <text x=\"585\" y=\"28\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10\" font-weight=\"700\">ACR 4–6 : biopsie</text>\n          <line x1=\"431\" y1=\"36\" x2=\"431\" y2=\"132\" stroke=\"var(--spe-infectio)\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n          <rect x=\"26\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--ink-muted)\"/>\n          <text x=\"74\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 0</text>\n          <text x=\"74\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Incomplet</text>\n          <text x=\"74\" y=\"126\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\" font-weight=\"600\">Complément</text>\n          <rect x=\"128\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-pneumo)\"/>\n          <text x=\"176\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 1</text>\n          <text x=\"176\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Normal</text>\n          <text x=\"176\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"10.5\" font-weight=\"600\">Rien</text>\n          <rect x=\"230\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-pneumo)\"/>\n          <text x=\"278\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 2</text>\n          <text x=\"278\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Bénin</text>\n          <text x=\"278\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"10.5\" font-weight=\"600\">Rien</text>\n          <rect x=\"332\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-orl)\"/>\n          <text x=\"380\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 3</text>\n          <text x=\"380\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Proba. bénin</text>\n          <text x=\"380\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-orl)\" font-size=\"10.5\" font-weight=\"600\">Surv.<span class=\"kw-chiffre\"> 6 mois</span></text>\n          <rect x=\"434\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-infectio)\"/>\n          <text x=\"482\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 4</text>\n          <text x=\"482\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Suspect</text>\n          <text x=\"482\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10.5\" font-weight=\"600\">Biopsie</text>\n          <rect x=\"536\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-infectio)\"/>\n          <text x=\"584\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 5</text>\n          <text x=\"584\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Malignité</text>\n          <text x=\"584\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10.5\" font-weight=\"600\">Biopsie</text>\n          <rect x=\"638\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-neuro)\"/>\n          <text x=\"686\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 6</text>\n          <text x=\"686\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Cancer prouvé</text>\n          <text x=\"686\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-neuro)\" font-size=\"10.5\" font-weight=\"600\">PEC onco</text>\n        </svg>\n        <figcaption>Seuil décisif <strong>ACR 3 → 4</strong> : ACR <span class=\"kw-chiffre\">≤ 3</span> se surveille, ACR ≥ 4 impose une <strong>biopsie</strong> histologique.</figcaption>\n      </figure>\n      <h4><span class=\"kw-imagerie\">Échographie</span> axillaire — au même titre que la mammo-écho mammaire</h4>\n      <p>Indiquée devant <strong>toute anomalie clinique mammaire</strong>. Recherche d'<span class=\"kw-clinique\">adénopathie axillaire suspecte</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Signe suspect (cytoponction justifiée si <span class=\"kw-chiffre\">≥ 1</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-radio\">Épaississement cortical</span> focal ou global</td></tr>\n          <tr><td><span class=\"kw-radio\">Absence de hile graisseux et vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-def\">échographie</span> est systématiquement <span class=\"kw-clinique\">associée à la mammographie</span> chez la femme jeune et chez les patientes à densité mammaire élevée (type C/D <span class=\"kw-alerte\">ACR</span>). Chez la femme enceinte ou de <span class=\"kw-chiffre\">&lt; 30 ans</span>, l'<span class=\"kw-imagerie\">échographie</span> remplace la <span class=\"kw-imagerie\">mammographie</span> en 1<sup>ère</sup> intention.</div>","frequence":3},{"id":"312-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la biopsie mammaire","contenu":"<p>La <span class=\"kw-ttt\">biopsie</span> mammaire confirme le diagnostic histologique (type, <span class=\"kw-def\">grade</span>, sous-type moléculaire) avant toute prise en charge thérapeutique. Toutes les lésions classées <span class=\"kw-clinique\">ACR 4 ou ACR 5</span> doivent faire l'objet d'une analyse histologique. Les <strong><span class=\"kw-radio\">ACR 3</span></strong> sont surveillées ; les <strong><span class=\"kw-radio\">ACR 2</span></strong> ne se biopsient pas.</p>\n      <h4>Trois techniques principales</h4>\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Aiguille</th><th>Indication principale</th><th>Guidage</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Microbiopsie</strong></td>\n            <td><span class=\"kw-chiffre\">14 G</span></td>\n            <td><span class=\"kw-clinique\">Masse</span> ou adénopathie palpable ou repérable en <span class=\"kw-imagerie\">échographie</span></td>\n            <td><span class=\"kw-imagerie\">Échoguidé</span></td>\n          </tr>\n          <tr>\n            <td><strong>Macrobiopsie</strong></td>\n            <td><span class=\"kw-chiffre\">10 G</span></td>\n            <td>Foyer de <span class=\"kw-radio\">microcalcifications</span> non palpable, non visible en <span class=\"kw-imagerie\">échographie</span></td>\n            <td><span class=\"kw-imagerie\">Stéréotaxique</span> (radioguidage)</td>\n          </tr>\n          <tr>\n            <td><strong>Punch-<span class=\"kw-ttt\">biopsie</span> cutanée</strong></td>\n            <td>—</td>\n            <td><span class=\"kw-clinique\">Lésion</span> cutanée évocatrice de <span class=\"kw-alerte\">maladie de Paget</span> ou cancer avec atteinte cutanée</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Indications de <span class=\"kw-ttt\">biopsie</span></h4>\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Contexte / Technique privilégiée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">ACR 4 ou ACR 5</span></td><td>Mammographie, <span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">IRM</span> — <span class=\"kw-clinique\">microbiopsie 14G échoguidée</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Discordance clinico-radiologique</span></td><td>Quelle que soit la classe <span class=\"kw-alerte\">ACR</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénopathie</span> axillaire suspecte (écho)</td><td><span class=\"kw-clinique\">Cytoponction</span> + microbiopsie si doute</td></tr>\n          <tr><td><span class=\"kw-clinique\">Lésion</span> cutanée évoquant <span class=\"kw-alerte\">maladie de Paget</span></td><td><span class=\"kw-clinique\">Punch-biopsie cutanée</span></td></tr>\n          <tr><td>Adénofibrome chez femme <span class=\"kw-chiffre\">&gt; 30 ans</span></td><td>Microbiopsie échoguidée</td></tr>\n          <tr><td>Adénofibrome avec ATCD familiaux, imagerie atypique ou croissance rapide</td><td>Microbiopsie échoguidée</td></tr>\n          <tr><td>Lésions atypiques (hyperplasie atypique, CLIS, papillome)</td><td><span class=\"kw-alerte\">Exérèse chirurgicale</span> souvent indiquée (sous-estimation possible)</td></tr>\n        </tbody>\n      </table>\n      <h4>Données fournies par l'analyse</h4>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Type histologique</strong></td><td><span class=\"kw-clinique\">Carcinome canalaire infiltrant</span> (<span class=\"kw-chiffre\">~90 %</span>), <span class=\"kw-clinique\">lobulaire infiltrant</span> (<span class=\"kw-chiffre\">~10 %</span>), in situ, autres rares</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Grade</span> histopronostique d'<span class=\"kw-def\">Elston et Ellis</span></strong><br>(= <span class=\"kw-def\">Scarff-Bloom-Richardson</span> modifié = <span class=\"kw-def\">score de Nottingham</span>)</td><td><span class=\"kw-bio\">Différenciation</span> + atypies nucléaires + mitoses, coté 1 à 3 pour chaque paramètre. <span class=\"kw-def\">Grade</span> 1 (3-5), <span class=\"kw-chiffre\">Grade 2</span> (6-7), Grade 3 (8-9).</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Immunohistochimie</span></strong></td><td>Récepteurs hormonaux (RO, <span class=\"kw-imagerie\">RP</span> — positifs si <span class=\"kw-chiffre\">≥ 10 %</span>), <span class=\"kw-bio\">HER2</span> (0, +, ++, +++ — <span class=\"kw-bio\">FISH</span> si HER2++), <span class=\"kw-bio\">Ki67</span> (prolifération)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Emboles vasculaires</span> lymphatiques</strong></td><td>Recherche systématique (<span class=\"kw-clinique\">facteur pronostique</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4>Cytoponction (place limitée)</h4>\n      <p>Utilisée pour : <span class=\"kw-clinique\">adénopathies</span> (<span class=\"kw-clinique\">cytoponction ganglionnaire systématique</span> si suspicion en <span class=\"kw-imagerie\">échographie</span> axillaire), <span class=\"kw-clinique\">lésions liquidiennes</span>, <span class=\"kw-clinique\">écoulements mamelonnaires</span>. <span class=\"kw-alerte\">Une cytoponction négative n'élimine pas une atteinte ganglionnaire</span>. Au niveau mammaire, la cytologie ne peut pas distinguer in situ <span class=\"kw-bio\">vs</span> infiltrant — son intérêt est très limité.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-clinique\">lésion</span> <span class=\"kw-radio\">ACR 3</span> se surveille à<span class=\"kw-chiffre\"> 6 mois</span> et ne se <span class=\"kw-ttt\">biopsie</span> pas en <span class=\"kw-chiffre\">première intention</span>. À l'inverse, dès qu'une lésion est classée <span class=\"kw-radio\">ACR 4</span>, l'<span class=\"kw-clinique\">analyse histologique est obligatoire</span> — la cytoponction seule ne suffit pas.</div>","frequence":3},{"id":"312-10","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types de lésions bénignes et de tumeurs malignes du sein","contenu":"<p>Trois grandes catégories d'entités à distinguer : <strong>lésions bénignes simples</strong> (pas de risque de cancer), <strong>lésions bénignes à risque</strong> (<span class=\"kw-ttt\">chirurgie</span> souvent indiquée) et <strong>tumeurs malignes</strong> (<span class=\"kw-clinique\">in situ</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">invasif</span>).</p>\n      <h4>Lésions bénignes simples — pas de sur-risque de cancer</h4>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques cliniques</th><th>Risque / PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Adénofibrome</span> (fibroadénome)</td>\n            <td>Tumeur la plus fréquente de la <span class=\"kw-chiffre\">femme &lt; 30 ans</span>. <span class=\"kw-clinique\">Prolifération mixte épithéliale et conjonctive</span>. <span class=\"kw-clinique\">Nodule unique ou multiple, indolore, bien limité, mobile, ferme « caoutchouteux »</span>, <span class=\"kw-chiffre\">&lt; 3 cm</span>. Écho : <span class=\"kw-clinique\">masse</span> <span class=\"kw-radio\">hypoéchogène</span>, ovale, bords réguliers, grand axe parallèle à la peau, <span class=\"kw-radio\">macrocalcifications</span> possibles.</td>\n            <td>Pas de sur-risque. <span class=\"kw-clinique\">Surveillance annuelle clinique</span> ± écho. <span class=\"kw-clinique\">Microbiopsie</span> si <span class=\"kw-chiffre\">&gt; 30 ans</span>, imagerie atypique, croissance rapide. <span class=\"kw-ttt\">Chirurgie</span> si gêne, douleur, <span class=\"kw-clinique\">lésion</span> volumineuse, ou après <span class=\"kw-chiffre\">35 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Mastopathie fibrokystique (MFK)</span></td>\n            <td>Maladie bénigne la plus fréquente entre <span class=\"kw-chiffre\">35-50 ans</span>. <span class=\"kw-clinique\">Mastodynies cycliques</span> pré-menstruelles, <span class=\"kw-clinique\">placards granuleux sensibles</span>, <span class=\"kw-clinique\">kystes mammaires</span>, <span class=\"kw-clinique\">écoulement jaune/verdâtre/blanchâtre</span>. <span class=\"kw-imagerie\">Échographie</span> : Kystes simples : <span class=\"kw-clinique\">masse</span> <span class=\"kw-radio\">anéchogène</span> arrondie bien limitée <span class=\"kw-radio\">avec renforcement postérieur</span>. Kystes atypiques : parois épaisses irrégulières, végétations intrakystiques.</td>\n            <td>Pas de sur-risque (sauf hyperplasie atypique associée). PEC : <span class=\"kw-ttt\">règles hygiéno-diététiques</span> (soutien-gorge, ↓ tabac/café/alcool), <span class=\"kw-ttt\">progestatifs</span> en 2<sup>e</sup> partie de cycle. <span class=\"kw-ttt\">Chirurgie</span> rare (kyste atypique, récidive après ponctions itératives).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Hamartome</span></td>\n            <td><span class=\"kw-clinique\">Lésion</span> rare, tissu glandulaire + fibreux + adipeux mêlés</td>\n            <td>Pas de <span class=\"kw-ttt\">chirurgie</span> ni de <span class=\"kw-def\">surveillance</span> spécifique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Cytostéatonécrose</span></td>\n            <td>Autodigestion du tissu adipeux par les lipases adipocytaires. Souvent <span class=\"kw-clinique\">post-traumatisme</span>, <span class=\"kw-clinique\">post-chirurgie ou post-radiothérapie</span>. Aspect parfois inquiétant (rétraction cutanée, densification, inflammation)</td>\n            <td>Imagerie redresse le diagnostic. Régression spontanée dans <span class=\"kw-chiffre\">90 %</span> des cas. <span class=\"kw-def\">Surveillance</span> simple, pas de <span class=\"kw-ttt\">chirurgie</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Lésions bénignes à risque de cancer — <span class=\"kw-ttt\">chirurgie</span> souvent indiquée</h4>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques</th><th>PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Hyperplasie canalaire atypique</span></td>\n            <td>RR <span class=\"kw-chiffre\">×4-5</span>. Souvent découverte sur microbiopsie pour <span class=\"kw-radio\">microcalcifications</span></td>\n            <td><span class=\"kw-alerte\">Exérèse chirurgicale</span> recommandée (risque de sous-estimation d'une <span class=\"kw-clinique\">lésion</span> cancéreuse sous-jacente)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Hyperplasie lobulaire atypique / Carcinome lobulaire in situ (CLIS)</span></td>\n            <td><span class=\"kw-alerte\">Pas un pré-cancer canalaire direct</span> mais <span class=\"kw-alerte\">marqueur de risque bilatéral diffus</span>. Classé dans les <strong>lésions bénignes à risque</strong> (à la différence du CCIS)</td>\n            <td><span class=\"kw-ttt\">Exérèse</span> + <span class=\"kw-def\">surveillance</span> rapprochée bilatérale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Papillome intra-canalaire</span></td>\n            <td>Prolifération épithéliale intra-canaliculaire. <span class=\"kw-clinique\">Écoulement mamelonnaire parfois sanglant</span></td>\n            <td><span class=\"kw-alerte\">Exérèse chirurgicale</span> (sauf petite <span class=\"kw-clinique\">lésion</span> totalement disparue après <span class=\"kw-clinique\">macrobiopsie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tumeur phyllode</span></td>\n            <td>Double composante fibro-épithéliale. <strong>Principal <span class=\"kw-def\">diagnostic différentiel</span> de l'adénofibrome</strong>. Bénin à malin selon le <span class=\"kw-def\">grade</span></td>\n            <td><span class=\"kw-alerte\">Exérèse chirurgicale</span> recommandée</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Tumeurs malignes — typologie</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Carcinome</span> canalaire in situ (CCIS)</strong></td>\n            <td>Non infiltrant</td>\n            <td><span class=\"kw-def\">Vrai pré-cancer</span>. Pas de franchissement de la <span class=\"kw-def\">membrane basale</span>, <span class=\"kw-clinique\">risque métastatique nul</span>. <span class=\"kw-clinique\">Évolution</span> possible en plusieurs années vers un cancer invasif. PEC : <span class=\"kw-ttt\">chirurgie</span> systématique avec marge <span class=\"kw-chiffre\">≥ 2 mm</span>, pas de traitement systémique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Carcinome</span> canalaire infiltrant</strong> (= carcinome infiltrant non spécifique)</td>\n            <td><span class=\"kw-chiffre\">~90 %</span></td>\n            <td>Forme la plus fréquente</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Carcinome</span> lobulaire infiltrant</strong></td>\n            <td><span class=\"kw-chiffre\">~10 %</span></td>\n            <td>Souvent <span class=\"kw-clinique\">multifocal</span> ou <span class=\"kw-clinique\">bilatéral</span>. Cellules infiltrant « en file indienne » (perte de l'<span class=\"kw-bio\">E-cadhérine</span>). Dissémination volontiers péritonéale.</td>\n          </tr>\n          <tr>\n            <td><strong>Formes rares</strong></td>\n            <td>—</td>\n            <td><span class=\"kw-clinique\">Carcinome médullaire</span> (à évoquer pour BRCA), mucineux, tubuleux, papillaire, lymphomes, sarcomes, métastases intra-mammaires</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Sous-types moléculaires (sur tout cancer infiltrant)</h4>\n      <table >\n        <thead>\n          <tr><th>Sous-type</th><th>RH</th><th>HER2</th><th>Ki67</th><th>Traitement principal</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Luminal A</td><td><span class=\"kw-bio\">RO</span>+ / <span class=\"kw-bio\">RP</span> <span class=\"kw-chiffre\">≥ 20 %</span></td><td>Négatif</td><td><span class=\"kw-chiffre\">&lt; 20 %</span></td><td><span class=\"kw-ttt\">Hormonothérapie</span></td></tr>\n          <tr><td>Luminal B</td><td>RO+ / <span class=\"kw-imagerie\">RP</span> &lt;<span class=\"kw-chiffre\"> 20 %</span></td><td>Négatif</td><td><span class=\"kw-chiffre\">≥ 20 %</span></td><td>Hormonothérapie + <span class=\"kw-ttt\">chimiothérapie</span></td></tr>\n          <tr><td>HER2+ (<span class=\"kw-chiffre\">15 %</span>)</td><td>+ ou −</td><td>Positif</td><td>Mauvais <span class=\"kw-def\">pronostic</span></td><td><span class=\"kw-ttt\">Trastuzumab</span> + <span class=\"kw-ttt\">chimiothérapie</span> ± hormonothérapie si RH+</td></tr>\n          <tr><td>Triple négatif (<span class=\"kw-chiffre\">15 %</span>)</td><td>Négatifs</td><td>Négatif</td><td>Très mauvais <span class=\"kw-def\">pronostic</span></td><td><span class=\"kw-ttt\">Chimiothérapie systématique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Ne pas confondre <span class=\"kw-alerte\">CCIS</span> (<span class=\"kw-clinique\">carcinome</span> <em>canalaire</em> in situ — vrai pré-cancer, <span class=\"kw-ttt\">chirurgie</span> systématique) et <span class=\"kw-alerte\">CLIS</span> (carcinome <em>lobulaire</em> in situ — classé dans les lésions bénignes à risque, marqueur de risque bilatéral). Le CCIS impose un traitement local complet ; le CLIS impose une <span class=\"kw-def\">surveillance</span> rapprochée bilatérale.</div>","frequence":2},{"id":"312-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes du bilan d'extension d'un cancer du sein","contenu":"<p>Le <span class=\"kw-def\">bilan d'extension</span> est indispensable avant le protocole thérapeutique du cancer du sein <strong>infiltrant</strong>. Il comprend un <strong>bilan loco-régional</strong> systématique, un <strong>bilan à distance</strong> ciblé selon le <span class=\"kw-def\">stade</span> et un <strong><span class=\"kw-def\">bilan préthérapeutique</span></strong> <span class=\"kw-ttt\">biologique</span>. La <span class=\"kw-clinique\">stadification</span> est résumée par le <span class=\"kw-def\">TNM</span> (<span class=\"kw-def\">cTNM</span> clinique, <span class=\"kw-def\">pTNM</span> anatomopathologique, <span class=\"kw-def\">ypTNM</span> après néoadjuvant).</p>\n      <h4>Bilan loco-régional (systématique)</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Mammographie bilatérale</span></li>\n        <li><span class=\"kw-imagerie\">Échographie mammaire</span></li>\n        <li><span class=\"kw-imagerie\">Échographie axillaire</span> ± cytoponction d'<span class=\"kw-clinique\">adénopathie</span> suspecte</li>\n      </ul>\n      <h4><span class=\"kw-imagerie\">IRM</span> mammaire — indications ciblées (rang C)</h4>\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Justification clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Oncoplastie majeure</span> (prothèse mammaire)</td><td>Mammographie/écho peu informatives</td></tr>\n          <tr><td>Femme <span class=\"kw-chiffre\">&lt; 40 ans</span></td><td>Seins denses, sensibilité mammo réduite</td></tr>\n          <tr><td>Seins <span class=\"kw-radio\">denses ACR C/D</span> non évaluables</td><td>Densité masque les lésions en mammo</td></tr>\n          <tr><td><span class=\"kw-clinique\">Carcinome lobulaire infiltrant</span></td><td>Volontiers <span class=\"kw-alerte\">multifocal et bilatéral</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénomégalie métastatique</span> sans anomalie mammo/écho</td><td>Recherche tumeur primitive mammaire occulte</td></tr>\n          <tr><td>Discordance radio-clinique sur la <span class=\"kw-chiffre\">taille tumorale</span></td><td>Préciser avant traitement conservateur</td></tr>\n          <tr><td>Avant <span class=\"kw-ttt\">chimiothérapie néoadjuvante</span></td><td>Bilan initial pour évaluation de la réponse</td></tr>\n          <tr><td>Recherche de tumeur primitive si imagerie négative</td><td>Métastases révélatrices sans primitif évident</td></tr>\n        </tbody>\n      </table>\n      <h4>Bilan à distance — indications formelles (<span class=\"kw-clinique\">carcinome</span> infiltrant)</h4>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Bilan à distance</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Tumeurs <span class=\"kw-chiffre\">≥ 3 cm</span></td>\n            <td><span class=\"kw-imagerie\">Oui</span></td>\n          </tr>\n          <tr>\n            <td>Tumeurs avec atteinte <span class=\"kw-clinique\">cutanée</span>, <span class=\"kw-clinique\">musculaire</span> ou <span class=\"kw-clinique\">inflammatoire</span> (stades T4)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Envahissement</span> ganglionnaire <strong>N+</strong> (cytoponction ou post-<span class=\"kw-ttt\">chirurgie</span>)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td>Signes d'appel cliniques de métastase</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td>Tumeurs <strong>T2</strong> avec sous-type <span class=\"kw-alerte\">triple négatif</span> ou <span class=\"kw-alerte\">HER2+</span></td>\n            <td>Oui (selon collège de gynécologie)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Carcinome in situ</span> (CCIS)</td>\n            <td><strong>Non</strong> — pas de risque de dissémination</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Options techniques (hiérarchie selon disponibilité)</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">TEP-TDM au 18-FDG</span> ± <span class=\"kw-bio\">CA 15-3</span> + <span class=\"kw-bio\">ACE</span> — <strong>option préférée si disponible</strong></li>\n        <li><span class=\"kw-imagerie\">TDM TAP injectée</span> + <span class=\"kw-imagerie\">scintigraphie osseuse</span> ± <span class=\"kw-bio\">CA 15-3</span> + <span class=\"kw-bio\">ACE</span> — alternative</li>\n        <li><span class=\"kw-imagerie\">RX thoracique</span> + <span class=\"kw-imagerie\">écho abdominale</span> + <span class=\"kw-imagerie\">scintigraphie osseuse</span> — <span class=\"kw-alerte\">à défaut</span> uniquement</li>\n        <li><span class=\"kw-imagerie\">IRM corps entier</span> chez la <span class=\"kw-clinique\">femme enceinte</span> (<span class=\"kw-clinique\">irradiation</span> <span class=\"kw-ci\">à éviter</span>)</li>\n      </ul>\n      <h4><span class=\"kw-def\">Bilan préthérapeutique</span> (biologie)</h4>\n      <p><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">bilan hépatique</span>. Le <span class=\"kw-bio\">CA 15-3</span> est <span class=\"kw-clinique\">optionnel</span> (peu sensible, peu spécifique, souvent négatif au diagnostic) — utile principalement au <span class=\"kw-def\">suivi</span> de la maladie métastatique.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Pas de <span class=\"kw-def\">bilan d'extension</span> dans le <strong>CCIS</strong> (risque métastatique nul). Pour le cancer infiltrant, l'indication formelle repose sur la taille, le T, le N et le sous-type moléculaire. Le <span class=\"kw-clinique\">carcinome lobulaire</span> a un bilan adapté (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">TEP</span> en raison du tropisme péritonéal).</div>","frequence":1},{"id":"312-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les objectifs et principes de traitement du cancer du sein","contenu":"<p>Les traitements visent à <strong><span class=\"kw-ttt\">exérèse</span> de la tumeur</strong>, <strong>traitement des éventuelles métastases</strong>, <strong><span class=\"kw-ttt\">réduction</span> du risque de récidive</strong>, <strong>ralentissement de l'<span class=\"kw-clinique\">évolution</span></strong> et <strong>amélioration de la qualité de vie</strong>. Toute décision est prise en <span class=\"kw-def\">RCP</span> (<span class=\"kw-def\">réunion de concertation pluridisciplinaire</span>) et formalisée dans un <span class=\"kw-def\">programme personnalisé de soins (PPS)</span>. <span class=\"kw-clinique\">PEC à 100 %</span> par la sécurité sociale.</p>\n      <h4><span class=\"kw-ttt\">Chirurgie</span> mammaire</h4>\n      <table >\n        <thead>\n          <tr><th>Option</th><th>Principe</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitement conservateur</strong></td>\n            <td>Tumorectomie (palpable) ou zonectomie / mastectomie partielle (non palpable) <strong>+ <span class=\"kw-ttt\">radiothérapie mammaire</span> systématique</strong></td>\n            <td>Tumeur de petite taille par rapport au volume du sein, unique, accessible</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement radical (mastectomie totale)</strong></td>\n            <td>Ablation du sein, du revêtement cutané et du mamelon</td>\n            <td>\n              <ul>\n                <li>Cancer du sein <span class=\"kw-alerte\">inflammatoire (T4d)</span></li>\n                <li>Lésions <span class=\"kw-clinique\">multifocales</span> dans des quadrants différents</li>\n                <li>Tumeur <span class=\"kw-chiffre\">&gt; 5 cm</span> par rapport au volume du sein</li>\n                <li>Insuffisamment réduit par traitement systémique néoadjuvant</li>\n                <li><span class=\"kw-ci\">CI à la radiothérapie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Reconstruction mammaire</strong></td>\n            <td>Immédiate (cas par cas) ou secondaire (<span class=\"kw-chiffre\">≥ 12 mois</span> après fin de la <span class=\"kw-imagerie\">RT</span>)</td>\n            <td>Après mastectomie totale</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-ttt\">Chirurgie</span> axillaire</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Ganglion sentinelle</span> :</strong> <span class=\"kw-clinique\">1<sup>er</sup> relais ganglionnaire</span> repéré par injection de <span class=\"kw-ttt\">gadolinium</span> et/ou colorant (<span class=\"kw-ttt\">bleu patenté</span>, <span class=\"kw-ttt\">vert d'indocyanine</span>). Indication : tumeur <span class=\"kw-chiffre\">cT1 à T3</span> + absence d'atteinte ganglionnaire prouvée en pré-opératoire. <span class=\"kw-clinique\">Évite le curage axillaire</span> si négatif.</li>\n        <li><strong>Curage axillaire :</strong> indiqué si <span class=\"kw-clinique\">GS métastatique</span>, tumeur cT4, ou N+ prouvé en cytologie. Complications : <span class=\"kw-clinique\">lymphœdème</span> du membre supérieur, <span class=\"kw-clinique\">troubles sensitifs</span>, <span class=\"kw-clinique\">lymphocèle</span>, <span class=\"kw-clinique\">hématome</span>, <span class=\"kw-clinique\">enraidissement de l'épaule</span>.</li>\n      </ul>\n      <h4><span class=\"kw-ttt\">Radiothérapie</span></h4>\n      <ul>\n        <li><strong>Mammaire :</strong> systématique après traitement conservateur (<span class=\"kw-imagerie\">RT</span> externe + boost sur le lit opératoire)</li>\n        <li><strong>Pariétale :</strong> après mastectomie totale si FDR de mauvais <span class=\"kw-def\">pronostic</span> (T <span class=\"kw-chiffre\">&gt; 5 cm</span>, pN+, âge <span class=\"kw-chiffre\">&lt; 35 ans</span>, <span class=\"kw-def\">grade</span> 3, emboles tumoraux)</li>\n        <li><strong>Ganglionnaire :</strong> systématique si <strong>N+</strong> axillaire</li>\n      </ul>\n      <h4><span class=\"kw-ttt\">Chimiothérapie</span></h4>\n      <p>Polychimiothérapie : <span class=\"kw-ttt\">anthracyclines</span> + <span class=\"kw-ttt\">cyclophosphamide</span> ± <span class=\"kw-ttt\">taxanes</span> (<span class=\"kw-ttt\">docétaxel</span>, <span class=\"kw-ttt\">paclitaxel</span>). Indiquée pour ~<span class=\"kw-chiffre\">30 %</span> des cancers infiltrants.</p>\n      <ul>\n        <li><strong>Néoadjuvante</strong> (pré-opératoire) : cancers inflammatoires, tumeurs <span class=\"kw-chiffre\">&gt; 1 cm</span> triple négatif ou HER2+, <span class=\"kw-bio\">envahissement</span> ganglionnaire massif (<span class=\"kw-chiffre\">cN2/N3</span>), tumeurs limites pour conservation</li>\n        <li><strong>Adjuvante</strong> (post-opératoire) : si FDR de mauvais <span class=\"kw-def\">pronostic</span> (âge <span class=\"kw-chiffre\">&lt; 35 ans</span>, T <span class=\"kw-chiffre\">≥ 2 cm</span>, N+, <span class=\"kw-def\">grade</span> 3, emboles, Ki67 <span class=\"kw-chiffre\">&gt; 20 %</span>, <span class=\"kw-bio\">RH−</span>, <span class=\"kw-bio\">HER2+</span>, cancer <span class=\"kw-etio\">inflammatoire</span>)</li>\n      </ul>\n      <h4>Thérapies ciblées</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Trastuzumab</span> (anti-HER2) : si <span class=\"kw-bio\">HER2+++</span> ou HER2++ avec <span class=\"kw-bio\">amplification FISH</span>. Durée <span class=\"kw-chiffre\">1 an</span> (18 perfusions). <span class=\"kw-alerte\">Cardiotoxique</span> → <span class=\"kw-def\">surveillance</span> de la <strong>FEVG</strong> (<span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scintigraphie</span> cardiaque).</li>\n        <li><span class=\"kw-ttt\">T-DM1</span> : trastuzumab couplé à l'<span class=\"kw-ttt\">emtansine</span> (résidu <span class=\"kw-etio\">tumoral</span> après chimio néoadjuvante)</li>\n        <li><span class=\"kw-ttt\">Anti-PARP</span> : cancers <span class=\"kw-bio\">BRCA-mutés</span> (germinale ou somatique)</li>\n      </ul>\n      <h4>Hormonothérapie</h4>\n      <p>Indiquée si <span class=\"kw-bio\">RH+</span> (RO et/ou <span class=\"kw-imagerie\">RP</span> <span class=\"kw-chiffre\">≥ 10 %</span>). Prescrite en situation <strong>adjuvante</strong> après les traitements initiaux. Durée minimale <span class=\"kw-chiffre\">5 ans</span>, parfois étendue à <span class=\"kw-chiffre\">10 ans</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Statut</th><th>Molécule</th><th>Effets secondaires spécifiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Avant ménopause</td>\n            <td><span class=\"kw-ttt\">Tamoxifène</span> (<span class=\"kw-def\">SERM</span>) ± <span class=\"kw-ttt\">analogues LH-RH</span> si &lt;<span class=\"kw-chiffre\"> 35 ans</span> + facteurs de gravité</td>\n            <td><span class=\"kw-alerte\">MTEV</span>, <span class=\"kw-alerte\">cancer de l'endomètre</span>, <span class=\"kw-clinique\">leucorrhées</span>, <span class=\"kw-clinique\">hypercalcémie</span>. <span class=\"kw-clinique\">Protecteur osseux</span>.</td>\n          </tr>\n          <tr>\n            <td>Après ménopause</td>\n            <td><span class=\"kw-ttt\">Inhibiteurs d'aromatase</span> (<span class=\"kw-ttt\">anastrozole, létrozole, exémestane</span>). Tamoxifène possible si CI aux IA.</td>\n            <td><span class=\"kw-clinique\">Arthralgies, myalgies</span>, <span class=\"kw-clinique\">dyslipidémie</span>, troubles de l'humeur, <span class=\"kw-alerte\">accentuation de la déminéralisation osseuse</span>. <span class=\"kw-ci\">CI en monothérapie chez la non-ménopausée</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Précautions sous inhibiteurs d'aromatase : <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">densitométrie osseuse</span>, apport <span class=\"kw-ttt\">calcium + vitamine D</span>, <span class=\"kw-ttt\">bisphosphonates</span> si FDR de fracture.</p>\n      <h4>Décision selon le sous-type (résumé)</h4>\n      <table >\n        <thead>\n          <tr><th>Sous-type</th><th><span class=\"kw-ttt\">Chirurgie</span></th><th><span class=\"kw-ttt\">Chimiothérapie</span></th><th><span class=\"kw-ttt\">Radiothérapie</span></th><th>Hormonothérapie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Luminal A (cN−)</td><td>Selon volume + GS</td><td>Rare (stades T3/T4, N+)</td><td>Mammaire si conservateur</td><td><strong>Systématique</strong></td></tr>\n          <tr><td>Luminal B (cN−)</td><td>Selon volume + GS</td><td>Selon FDR de récidive</td><td>Mammaire si conservateur</td><td><strong>Systématique</strong></td></tr>\n          <tr><td>Triple négatif (cN−)</td><td>Selon volume + GS</td><td><strong>Systématique</strong>, souvent néoadjuvante</td><td>Mammaire si conservateur</td><td>Non</td></tr>\n          <tr><td>HER2+ (cN−)</td><td>Selon volume + GS</td><td><strong>Systématique</strong> + <span class=\"kw-ttt\">trastuzumab ± T-DM1</span></td><td>Mammaire si conservateur</td><td>Si RH+</td></tr>\n          <tr><td>N+ (cN+)</td><td>Selon volume + <strong>curage axillaire</strong></td><td><strong>Systématique</strong></td><td><strong>Locorégionale systématique</strong></td><td>Si RH+</td></tr>\n          <tr><td><span class=\"kw-etio\">Inflammatoire</span> (T4d)</td><td><strong>Mastectomie totale + curage</strong></td><td><strong>Systématique, néoadjuvante</strong> ± anti-HER2</td><td><strong>Locorégionale systématique</strong></td><td>Si RH+</td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-def\">Surveillance</span> après traitement</h4>\n      <ul>\n        <li><strong>Clinique :</strong> tous les <span class=\"kw-chiffre\">3-6 mois</span> pendant <span class=\"kw-chiffre\">5 ans</span>, puis 1×/an à vie ou jusqu'à la 10<sup>e</sup> année</li>\n        <li><strong>Imagerie :</strong> <span class=\"kw-imagerie\">mammographie</span> bilatérale + écho mammaire 1×/an à vie ou jusqu'à<span class=\"kw-chiffre\"> 10 ans</span> (sauf mastectomie)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-ttt\">tamoxifène</span> est un <span class=\"kw-alerte\">facteur de risque majeur de MTEV</span> (TVP / EP) et de <span class=\"kw-alerte\">cancer de l'endomètre</span> — toute métrorragie sous tamoxifène impose une <span class=\"kw-imagerie\">échographie</span> pelvienne et une consultation gynécologique. Le <span class=\"kw-ttt\">trastuzumab</span> est <span class=\"kw-alerte\">cardiotoxique</span> → FEVG avant et pendant le traitement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux · 322 — Décision thérapeutique personnalisée · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":7}],"astuces":[],"strategie":{"principes":"<p>Une <span class=\"kw-ttt\">chimiothérapie</span> est recommandée pour près de <span class=\"kw-chiffre\">30 %</span> des cancers du sein invasifs. Indications (néoadjuvant / adjuvant) discutées en <span class=\"kw-def\">RCP</span>.</p><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> — molécules</strong></p><ul><li>Polychimiothérapie : <span class=\"kw-ttt\">anthracycline</span> + <span class=\"kw-ttt\">cyclophosphamide</span> ± <span class=\"kw-ttt\">docétaxel / paclitaxel</span></li></ul><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> néoadjuvante (pré-opératoire)</strong></p><ul><li><span class=\"kw-alerte\">Cancers inflammatoires</span></li><li>Tumeurs agressives <span class=\"kw-chiffre\">&gt; 1 cm</span> (<span class=\"kw-clinique\">triple négatif</span> ou <span class=\"kw-clinique\">HER2+</span>)</li><li><span class=\"kw-bio\">Envahissement</span> ganglionnaire important (<span class=\"kw-clinique\">cN2/N3</span>)</li><li>Volume <span class=\"kw-etio\">tumoral</span> limite pour un traitement conservateur (objectif : <span class=\"kw-def\">réduire la taille</span>)</li></ul><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> adjuvante</strong></p><ul><li>FR de mauvais <span class=\"kw-def\">pronostic</span> : âge <span class=\"kw-chiffre\">&lt; 35 ans</span> ; tumeur <span class=\"kw-chiffre\">≥ 2 cm</span> (≥ T2) ; cancer <span class=\"kw-etio\">inflammatoire</span> ; <span class=\"kw-clinique\">N+</span> (FR principal) ; <span class=\"kw-def\">grade</span> 3 ; emboles ; résidu post-néoadjuvant ; Ki67 <span class=\"kw-chiffre\">&gt; 20 %</span> ; <span class=\"kw-clinique\">RH−</span> ; <span class=\"kw-clinique\">HER2+</span></li><li>Discutée selon les <span class=\"kw-def\">signatures transcriptomiques</span> (OncotypeDX®, Prosigna®, Mammaprint® — rang C)</li></ul><p><strong>Thérapie ciblée anti-HER2 — trastuzumab</strong></p><ul><li>AC monoclonal inhibant la prolifération des cellules surexprimant <span class=\"kw-clinique\">HER2</span></li><li>Indication : tumeur <span class=\"kw-clinique\">HER2+</span> (3+ ou 2+ avec amplification en hybridation in situ), <span class=\"kw-def\">toujours associé à la chimiothérapie</span></li><li>Durée <span class=\"kw-chiffre\">1 an</span> (18 perfusions) ; renforcement par <span class=\"kw-ttt\">T-DM1</span> si résidu <span class=\"kw-etio\">tumoral</span> après néoadjuvant</li><li><span class=\"kw-alerte\">Cardiotoxique</span> → <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">FEVG</span> (<span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scintigraphie</span> cardiaque)</li></ul><p><strong>Hormonothérapie — si RH+ (RO et/ou <span class=\"kw-imagerie\">RP</span> <span class=\"kw-chiffre\">≥ 10 %</span>)</strong></p><p><span class=\"kw-ci\">Anti-aromatases CI en monothérapie chez la femme non ménopausée</span> + accélèrent la perte osseuse → <span class=\"kw-def\">surveillance</span> DMO, calcium/vit. D ± biphosphonate</p><ul><li>En situation <span class=\"kw-ttt\">adjuvante</span>, à la fin des traitements initiaux ; durée minimale <span class=\"kw-chiffre\">5 ans</span> (jusqu’à <span class=\"kw-chiffre\">10 ans</span> si haut risque de récidive)</li><li><span class=\"kw-def\">Avant la ménopause</span> : <span class=\"kw-ttt\">tamoxifène</span> (SERM) ± analogues de la LH-RH (suppression ovarienne si &lt;<span class=\"kw-chiffre\"> 35 ans</span> + facteurs de gravité)</li><li><span class=\"kw-def\">Après la ménopause</span> : <span class=\"kw-ttt\">anti-aromatases</span> (anastrozole, létrozole, exémestane) ; tamoxifène possible si CI</li><li>Diminue le risque de récidive de <span class=\"kw-chiffre\">40 %</span> et le risque de décès par cancer du sein de <span class=\"kw-chiffre\">30 %</span></li></ul>","suivi":"<p><strong>Soins supports</strong></p><ul><li><span class=\"kw-ttt\">Anti-ostéoporotiques</span> (bisphosphonates, dénosumab) : systématiques si <span class=\"kw-clinique\">métastases osseuses</span> (&gt;<span class=\"kw-chiffre\"> 50 %</span> des M+) ; indispensables si <span class=\"kw-alerte\">hypercalcémie</span></li><li><span class=\"kw-ttt\">Activité physique adaptée</span> : ↓ <span class=\"kw-def\">mortalité</span>, ↓ récidive, ↓ symptômes liés au cancer et aux traitements (cancers localisés)</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> clinique</strong></p><ul><li>Tous les <span class=\"kw-chiffre\">3-6 mois</span> pendant les <span class=\"kw-chiffre\">5 premières années</span></li><li>Puis <span class=\"kw-chiffre\">1×/an</span> à vie ou jusqu’à la 10ᵉ année</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> par imagerie</strong></p><ul><li>Mammographie bilatérale + <span class=\"kw-imagerie\">échographie</span> mammaire</li><li><span class=\"kw-chiffre\">1×/an</span> à vie ou jusqu’à la 10ᵉ année (sauf si mastectomie)</li></ul>"},"liensGlobaux":[{"href":"https://www.depistagesein.ca/classification-bi-rads/#:~:text=La%20classification%20BI%2DRADS%20","label":"https://www.depistagesein.ca/classification-bi-rads/#:~:text=La%20classification%20BI%2DRADS%20"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Cancer du sein confirmé — non métastatique — Quel type histologique ?","detail":"<h4>CAT — Cancer du sein non métastatique — Du type histologique au geste thérapeutique</h4>","branches":[{"to":"t-ccis","label":"Carcinome canalaire in situ (CCIS)","color":"blue"},{"to":"q-operable","label":"Carcinome infiltrant","color":"blue"}]},{"id":"t-ccis","kind":"terminal","label":"CCIS — chirurgie sans traitement systémique","color":"blue","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Systématique</span> : <span class=\"kw-ttt\">exérèse</span> complète avec marge de tissu sain de <span class=\"kw-chiffre\">2 mm</span></li><li>Conservatrice si unifocal <span class=\"kw-chiffre\">&lt; 3 cm</span> (parfois au-delà selon le volume mammaire) → <span class=\"kw-ttt\">RT mammaire systématique</span></li><li>Radicale (mastectomie totale) si lésions étendues/multifocales → <span class=\"kw-ttt\">GS prélevé</span>, <span class=\"kw-ci\">pas de RT</span>, reconstruction immédiate possible</li></ul><h4>Traitement systémique</h4><ul><li><span class=\"kw-ci\">PAS de chimiothérapie ni d’hormonothérapie</span> (absence de risque métastatique à distance)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Rapprochée pendant <span class=\"kw-chiffre\">≥ 10 ans</span></li></ul>"},{"id":"q-operable","kind":"decision","label":"Opérabilité d’emblée ? — Volume tumoral vs sein · forme inflammatoire ?","branches":[{"to":"t-operable","label":"Opérable d’emblée","color":"green"},{"to":"t-neoadj","label":"Non opérable d’emblée (volume trop important)","color":"amber"},{"to":"t-inflammatoire","label":"Cancer inflammatoire (T4d)","color":"red"}]},{"id":"t-operable","kind":"terminal","label":"Chirurgie première + adjuvant","color":"green","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span> première</h4><ul><li><span class=\"kw-ttt\">Conservatrice</span> (tumorectomie/zonectomie) + <span class=\"kw-ttt\">RT mammaire</span>, OU <span class=\"kw-ttt\">mastectomie totale</span></li><li>Geste axillaire : <span class=\"kw-ttt\">ganglion sentinelle</span> (cT1-T3, N0) ou <span class=\"kw-ttt\">curage</span> (GS+, cT4, N+ prouvé)</li></ul><h4>Traitements adjuvants (<span class=\"kw-def\">RCP</span>)</h4><ul><li>Selon le <span class=\"kw-def\">sous-type</span> & les facteurs pronostiques</li><li><span class=\"kw-ttt\">Chimiothérapie</span> ± <span class=\"kw-ttt\">anti-HER2</span> (si HER2+) ± <span class=\"kw-ttt\">hormonothérapie</span> (si RH+) ± <span class=\"kw-ttt\">RT pariétale/ganglionnaire</span></li></ul>"},{"id":"t-neoadj","kind":"terminal","label":"Chimiothérapie néoadjuvante puis chirurgie","color":"amber","detail":"<h4><span class=\"kw-ttt\">Chimiothérapie</span> néoadjuvante</h4><ul><li>Objectif : <span class=\"kw-def\">réduire la taille lésionnelle</span> (triple négatif / HER2+ &gt;<span class=\"kw-chiffre\"> 1 cm</span>, cN2/N3, volume limite)</li></ul><h4><span class=\"kw-ttt\">Chirurgie</span> secondaire</h4><ul><li>Adaptée à la réponse au traitement</li><li><span class=\"kw-def\">Traitement conservateur parfois possible</span> si bonne réponse</li></ul><h4>Adjuvant</h4><ul><li>Selon le sous-type & la réponse (anti-HER2, hormonothérapie, <span class=\"kw-imagerie\">RT</span>)</li></ul>"},{"id":"t-inflammatoire","kind":"terminal","label":"Forme inflammatoire — séquence imposée","color":"red","detail":"<h4><span class=\"kw-ttt\">Chimiothérapie</span> néoadjuvante</h4><ul><li><span class=\"kw-ttt\">Systématique</span>, débutant en néoadjuvant ± <span class=\"kw-ttt\">anti-HER2</span></li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Mastectomie totale + curage axillaire</span> — <span class=\"kw-alerte\">quelle que soit la réponse</span> au traitement</li></ul><h4>Locorégional & systémique</h4><ul><li><span class=\"kw-ttt\">RT locorégionale systématique</span> ± hormonothérapie si RH+</li></ul>"}]},"cards":[{"i":"10ea5d53a672","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelle est la procédure décisionnelle pour le traitement du cancer du sein ?","a":"<p>Toute décision thérapeutique pour le cancer du sein est prise en <strong>Réunion de Concertation Pluridisciplinaire (RCP)</strong> et est formalisée dans un <strong>Programme Personnalisé de Soins (PPS)</strong>. La prise en charge est à <strong>100% par la Sécurité Sociale</strong>.</p>"},{"i":"6a40ca251686","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Comment est gérée la chirurgie axillaire dans le traitement du cancer du sein ?","a":"<p>La chirurgie axillaire implique :</p><ul><li>Le <strong>ganglion sentinelle (GS)</strong> : identifié par injection de <strong>gadolinium</strong> et/ou <strong>colorant</strong> (bleu patenté, vert d'indocyanine). Il est indiqué pour les tumeurs cT1 à T3 en l'absence d'atteinte ganglionnaire prouvée en pré-opératoire, et permet d'éviter le curage axillaire s'il est négatif.</li><li>Le <strong>curage axillaire</strong> : indiqué si le ganglion sentinelle est métastatique, en cas de tumeur cT4 ou d'atteinte ganglionnaire prouvée en cytologie.</li></ul>"},{"i":"8f85eda66b31","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les types de chirurgie mammaire et leurs indications principales ?","a":"<p>Il existe deux types principaux de chirurgie mammaire :</p><ul><li><strong>Traitement conservateur</strong> (tumorectomie, zonectomie ou mastectomie partielle) avec radiothérapie mammaire systématique : indiqué pour les tumeurs de <strong>petite taille</strong> par rapport au volume du sein, uniques et accessibles.</li><li><strong>Traitement radical</strong> (mastectomie totale : ablation du sein, du revêtement cutané et du mamelon) : indiqué pour le cancer du sein <strong>inflammatoire</strong> (T4d), les lésions <strong>multifocales</strong> dans différents quadrants, les tumeurs <strong>&gt; 5 cm</strong>, celles insuffisamment réduites par traitement néoadjuvant, ou en cas de contre-indication à la radiothérapie.</li></ul>"},{"i":"93bc658672b6","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les objectifs généraux du traitement du cancer du sein ?","a":"<p>Les objectifs du traitement du cancer du sein sont multiples :</p><ul><li><strong>Exérèse</strong> de la tumeur.</li><li>Traitement des éventuelles <strong>métastases</strong>.</li><li>Réduction du risque de <strong>récidive</strong>.</li><li><strong>Ralentissement de l'évolution</strong> de la maladie.</li><li>Amélioration de la <strong>qualité de vie</strong> du patient.</li></ul>"},{"i":"949227a54fcb","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelles sont les principales thérapies ciblées utilisées dans le cancer du sein et leurs spécificités ?","a":"<p>Les thérapies ciblées incluent :</p><ul><li>Le <strong>Trastuzumab</strong> (anti-HER2) : si HER2+++ ou HER2++ avec amplification FISH. Durée <strong>1 an</strong> (18 perfusions). Effet secondaire : <strong>cardiotoxique</strong>, nécessitant une surveillance de la <strong>FEVG</strong> (échographie ou scintigraphie cardiaque).</li><li>Le <strong>T-DM1</strong> (trastuzumab couplé à l'emtansine) : en cas de résidu tumoral après chimio néoadjuvante.</li><li>Les <strong>anti-PARP</strong> : pour les cancers BRCA-mutés (germinale ou somatique).</li></ul>"},{"i":"9d87700af0d3","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quand la chimiothérapie est-elle indiquée dans le traitement du cancer du sein et quel est son schéma habituel ?","a":"<p>La chimiothérapie, généralement une <strong>polychimiothérapie</strong> (anthracyclines + cyclophosphamide ± taxanes comme le docétaxel, paclitaxel), est indiquée pour environ <strong>30%</strong> des cancers infiltrants :</p><ul><li>En situation <strong>néoadjuvante</strong> (pré-opératoire) : pour les cancers inflammatoires, tumeurs &gt; 1 cm triple négatif ou HER2+, envahissement ganglionnaire massif (cN2/cN3), tumeurs limites pour la conservation.</li><li>En situation <strong>adjuvante</strong> (post-opératoire) : si facteurs de risque de mauvais pronostic (âge &lt; 35 ans, T ≥ 2 cm, N+, grade 3, emboles, Ki67 &gt; 20%, RH−, HER2+, cancer inflammatoire).</li></ul>"},{"i":"a0a5d1f5f00b","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quand l'hormonothérapie est-elle indiquée dans le cancer du sein et quelles sont les molécules utilisées selon le statut ménopausique ?","a":"<p>L'hormonothérapie est indiquée si le cancer est <strong>RH+ (récepteurs hormonaux positifs : RO et/ou RP ≥ 10%)</strong>. Elle est prescrite en situation <strong>adjuvante</strong> après les traitements initiaux, pour une durée minimale de <strong>5 ans</strong>, parfois étendue à 10 ans.</p><ul><li><strong>Avant la ménopause</strong> : <strong>Tamoxifène</strong> (SERM) ± analogues LH-RH si &lt; 35 ans et facteurs de gravité.</li><li><strong>Après la ménopause</strong> : <strong>Inhibiteurs d'aromatase</strong> (anastrozole, létrozole, exémestane). Le tamoxifène est possible en cas de contre-indication aux inhibiteurs d'aromatase.</li></ul>"},{"i":"c300ec21f8e6","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Dans quelles situations la radiothérapie est-elle indiquée pour le cancer du sein ?","a":"<p>La radiothérapie est indiquée dans plusieurs situations :</p><ul><li><strong>Mammaire</strong> : systématique après traitement conservateur (radiothérapie externe + boost sur le lit opératoire).</li><li><strong>Pariétale</strong> : après mastectomie totale si présence de facteurs de risque de mauvais pronostic (T &gt; 5 cm, pN+, âge &lt; 35 ans, grade 3, emboles tumoraux).</li><li><strong>Ganglionnaire</strong> : systématique si atteinte ganglionnaire axillaire (N+).</li></ul>"},{"i":"ce9bb7c4f400","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les effets secondaires spécifiques du tamoxifène et des inhibiteurs d'aromatase ?","a":"<p>Les effets secondaires spécifiques sont :</p><ul><li><strong>Tamoxifène</strong> : <strong>MTEV</strong> (Maladie ThromboEmbolique Veineuse), <strong>cancer de l'endomètre</strong>, leucorrhées, hypercalcémie. Il est protecteur osseux.</li><li><strong>Inhibiteurs d'aromatase</strong> : Arthralgies, myalgies, dyslipidémie, troubles de l'humeur, accentuation de la déminéralisation osseuse. Ils sont contre-indiqués en monothérapie chez la femme non-ménopausée.</li></ul>"},{"i":"fc3b4bb34a06","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelles sont les principales complications potentielles du curage axillaire ?","a":"<p>Les complications potentielles du curage axillaire incluent :</p><ul><li>Le <strong>lymphœdème du membre supérieur</strong>.</li><li>Les troubles sensitifs.</li><li>Le lymphocèle.</li><li>L'hématome.</li><li>L'enraidissement de l'épaule.</li></ul>"},{"i":"0b6184b25965","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Comment le carcinome in situ se distingue-t-il du carcinome invasif en termes de définition et de risque métastatique ?","a":"<ul><li>Le <strong>carcinome in situ</strong> est une évolution intra-épithéliale (dans le canal ou le lobule) : il n'y a pas de franchissement de la membrane basale et le risque métastatique est <strong>nul</strong>.</li><li>Le <strong>carcinome invasif (infiltrant)</strong> implique le franchissement de la membrane basale, ce qui lui confère un <strong>risque métastatique présent</strong> par voies lymphatique et hématogène.</li></ul>"},{"i":"8283588a4dd0","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelle est l'origine tissulaire du cancer du sein et quel est le rôle des œstrogènes dans sa carcinogenèse ?","a":"<p>Le cancer du sein naît des cellules de l'<strong>appareil sécrétoire du sein</strong> (lobules et canaux galactophores). La carcinogenèse est un processus multi-étapes, influencé par les <strong>œstrogènes</strong> dans 60-70 % des cas (cancer hormono-dépendant).</p>"},{"i":"9aa78c509a90","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelles sont les particularités de dissémination ou de récidive pour les sous-types moléculaires de cancer du sein : lobulaire infiltrant, HER2+, et triple négatif ?","a":"<ul><li>Le <strong>carcinome lobulaire infiltrant</strong> présente un <strong>tropisme péritonéal et pleural</strong> (carcinose).</li><li>Le sous-type <strong>HER2+</strong> a un <strong>tropisme cérébral</strong> (SNC) fréquent.</li><li>Le sous-type <strong>triple négatif</strong> est caractérisé par une <strong>récidive précoce</strong> (2-3 premières années) et un mauvais pronostic.</li></ul>"},{"i":"c1d84a404d0e","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Décrivez l'histoire naturelle du cancer du sein, de la cellule normale au carcinome invasif.","a":"<p>La cellule normale évolue en <strong>carcinome in situ</strong>, où la membrane basale est intacte et il n'y a pas de métastases. Après franchissement de cette membrane basale, il devient un <strong>carcinome invasif</strong>, qui est alors capable de métastaser.</p>"},{"i":"e7e404ce3d36","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelles sont les principales voies de dissémination du carcinome invasif du sein ?","a":"<p>Le carcinome invasif dissémine par :</p><ul><li>La <strong>voie lymphatique</strong>, atteignant principalement le <strong>creux axillaire</strong> (relais principal), puis les ganglions sus- et sous-claviculaires, et la chaîne mammaire interne.</li><li>La <strong>voie hématogène</strong>, touchant préférentiellement l'<strong>os</strong>, le <strong>poumon</strong>, et le <strong>foie</strong>.</li></ul>"},{"i":"2fb021ca617f","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Quel est le piège diagnostique primordial à connaître concernant le dépistage du cancer du sein ?","a":"<p>Un <strong>dépistage n'est jamais réalisé sur un sein déjà symptomatique</strong>. En présence de tout signe clinique suspect (<strong>nodule, écoulement, rétraction cutanée</strong>), il faut basculer immédiatement vers une <strong>démarche diagnostique</strong> et ne pas considérer cela comme du dépistage.</p>"},{"i":"76c6e7f7062e","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Quelle est la stratégie de dépistage du cancer du sein pour une femme considérée à haut risque, c'est-à-dire avec un antécédent personnel ou familial identifié ?","a":"<p>Pour les femmes à haut risque (ex: antécédent personnel d'hyperplasie atypique, de carcinome lobulaire in situ, de carcinome canalaire in situ, ou antécédent d'irradiation thoracique haute dose pour un Hodgkin), la stratégie de dépistage est <strong>individuelle</strong>. Elle repose sur une <strong>mammographie annuelle</strong> associée à une <strong>échographie annuelle</strong>.</p>"},{"i":"b0e068206283","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Comment est défini le dépistage du cancer du sein pour la population générale et quelle est la modalité principale préconisée ?","a":"<p>Pour les <strong>femmes âgées de 50 à 74 ans sans facteur de risque particulier</strong>, le dépistage s'inscrit dans un <strong>programme organisé</strong>. Il consiste en une <strong>mammographie bilatérale 2 incidences</strong> (oblique externe et cranio-caudale) réalisée <strong>tous les 2 ans</strong>.</p>"},{"i":"c65f6c0914ca","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"En présence d'une mutation génétique avérée de type BRCA1/2, TP53 ou PALB2, quelle est la stratégie de dépistage du cancer du sein mise en place ?","a":"<p>Pour les femmes porteuses de mutations génétiques délétères (BRCA1/2, TP53, PALB2, etc.), un <strong>programme personnalisé</strong> est instauré. Il comprend un <strong>examen clinique bisannuel dès 20 ans</strong> et une surveillance annuelle plus intensive entre 30 et 65 ans, associant <strong>IRM mammaire, mammographie et échographie</strong>.</p>"},{"i":"42f928fea87b","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelles modifications cutanées mammaires doivent faire suspecter une tumeur du sein ?","a":"<p>Les modifications cutanées suspectes sont :</p><ul><li>Rétraction cutanée, fossette, méplat (recherchés à l'éclairage jour frisant, bras pendants puis relevés)</li><li><strong>Squirrhe mammaire</strong> (tumeur dure avec épaississement et/ou bourgeonnement)</li><li>Ulcération cutanée, nodules de perméation</li><li>Empâtement, lésion croûteuse</li><li>Signes d'inflammation (dans le cadre d'un cancer inflammatoire) : placard érythémateux chaud, œdème cutané avec aspect de « <strong>peau d'orange</strong> » sur <strong>≥ 1/3</strong> du sein et d'évolution rapide en quelques semaines.</li></ul>"},{"i":"60a8646fa9e0","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Comment définit-on un cancer du sein inflammatoire (T4d) et quels en sont les signes cliniques ?","a":"<p>Le cancer du sein inflammatoire (T4d) est défini par l'association de <strong>quatre critères</strong> :</p><ul><li>Un <strong>placard érythémateux chaud</strong></li><li>Un <strong>œdème cutané</strong> avec un aspect de « <strong>peau d'orange</strong> »</li><li>La présence de ces signes sur <strong>≥ 1/3</strong> du sein</li><li>Une <strong>évolution rapide</strong> en quelques semaines</li></ul><p>Il nécessite une prise en charge spécifique avec mastectomie + curage + chimiothérapie néoadjuvante, quel que soit le sous-type.</p>"},{"i":"67b3bd61c6ed","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quels sont les signes cliniques suspect d'un écoulement mamelonnaire ?","a":"<p>Un écoulement mamelonnaire est suspect s'il est :</p><ul><li>Apparition <strong>récente</strong></li><li><strong>Spontané</strong></li><li><strong>Unilatéral</strong></li><li><strong>Unipore</strong></li><li>De couleur <strong>claire</strong>, <strong>jaune séreux</strong>, <strong>rouge sanglant</strong> ou <strong>noir</strong></li></ul>"},{"i":"8fb2973a7209","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelle est la conduite à tenir face à un nodule du sein chez une femme ménopausée ?","a":"<p>L'apparition d'un <strong>nodule du sein</strong> chez une femme ménopausée doit faire suspecter un <strong>cancer du sein</strong> jusqu'à preuve du contraire.</p>"},{"i":"d72813c16702","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelles sont les modifications du mamelon pouvant évoquer une tumeur du sein ?","a":"<p>Les modifications du mamelon à surveiller sont :</p><ul><li><strong>Déviation</strong>, <strong>invagination</strong> ou <strong>rétraction</strong> du mamelon</li><li>Un aspect <strong>eczématiforme</strong> du mamelon, d'autant plus s'il est persistant et unilatéral, qui doit faire évoquer une <strong>maladie de Paget du sein</strong> (nécessitant une punch-biopsie cutanée systématique).</li></ul>"},{"i":"24c35e79726a","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Dans quel contexte la mammographie est-elle indiquée en première intention pour le dépistage organisé du cancer du sein ?","a":"<p>La mammographie est indiquée en première intention dans le cadre du <strong>dépistage organisé</strong> chez les femmes âgées de <strong>50 à 74 ans</strong>, tous les <strong>2 ans</strong>, en l'absence de signes cliniques.</p>"},{"i":"7d98d123852e","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Quand la mammographie est-elle indiquée dans le cadre d'un dépistage individuel ou d'une démarche diagnostique ?","a":"<p>Elle est indiquée annuellement en <strong>dépistage individuel</strong> chez les femmes à <strong>haut risque</strong> (antécédents personnels/familiaux, irradiation thoracique, lésion à risque). Elle est également indiquée en <strong>démarche diagnostique</strong> devant <strong>toute anomalie clinique mammaire</strong> (nodule, écoulement suspect, rétraction, modification cutanée).</p>"},{"i":"bd80081aa249","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Dans quelles situations la mammographie est-elle contre-indiquée ou remplacée en première intention ?","a":"<p>La mammographie est <strong>contre-indiquée</strong> chez la <strong>femme très jeune (< 30 ans)</strong> et chez la <strong>femme enceinte</strong> (seins denses non lisibles). Dans ces cas, l'<strong>échographie</strong> remplace la mammographie en première intention.</p>"},{"i":"d97017374caf","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Quelles sont les indications de la mammographie dans le suivi du cancer du sein ?","a":"<p>La mammographie est systématiquement indiquée en <strong>bilan préthérapeutique</strong> (bilatérale avant traitement d'un cancer du sein) et pour la <strong>surveillance post-traitement</strong> (1 fois/an à vie ou jusqu'à la 10e année, sauf en cas de mastectomie totale).</p>"}]};